(() => {
  const $ = (s) => document.querySelector(s);
  const output = $("#output");
  const panelTitle = $("#panelTitle");
  const entries = [
    {en:"Aquilina of Byblos",ar:"القديسة أكويلينا من جبيل",letter:"A",status:"Saint · Martyr",place:"Byblos · جبيل",years:"3rd century",storyEn:"Aquilina is honoured in Christian tradition as a young woman from Byblos who remained faithful to Christ during the persecutions of the Roman Empire. Her witness made her one of the early Christian martyrs associated with the Lebanese coast. The details of her life come through ancient hagiographical tradition.",storyAr:"تكرّم التقاليد المسيحية أكويلينا كشابّة من مدينة جبيل تمسّكت بإيمانها بالمسيح في زمن الاضطهادات الرومانية. وقد جعلت شهادتها منها إحدى الشهيدات المسيحيات الأوائل المرتبطات بالساحل اللبناني. وتَرِد تفاصيل حياتها في المصادر التقليدية القديمة لسِيَر القديسين."},
    {en:"Barbara",ar:"القديسة بربارة",letter:"B",status:"Saint · Martyr",place:"Lebanon · in local tradition",years:"Early Christian tradition",storyEn:"Saint Barbara is widely venerated in Lebanon and across the Eastern Christian world. Christian tradition remembers her as a young woman who held to her faith despite opposition. The historical details of her story vary between traditions, so this account is presented as a tradition rather than a fully documented biography.",storyAr:"تحظى القديسة بربارة بإكرام واسع في لبنان وفي العالم المسيحي الشرقي. وتذكرها التقاليد المسيحية كشابّة تمسّكت بإيمانها رغم المعارضة. تختلف التفاصيل التاريخية لسيرتها بين التقاليد، لذلك تُعرض قصتها هنا بوصفها رواية تقليدية لا سيرة موثّقة بالكامل."},
    {en:"Charbel Makhlouf",ar:"القديس شربل مخلوف",letter:"C",status:"Canonized saint · 1977",place:"Bqaa Kafra & Annaya · بقاعكفرا وعنّايا",years:"1828–1898",storyEn:"Saint Charbel Makhlouf was born Youssef Antoun Makhlouf on 8 May 1828 in Bqaa Kafra, a mountain village in northern Lebanon. He was the youngest child of Antoun Zaarour Makhlouf and Brigitta (Brigitte) Yaacoub al-Chediak. His family lived simply and was known for its strong Christian faith. Youssef was baptised in the Church of Our Lady in Bqaa Kafra on 16 May 1828. When he was still a very young child, his father died while away from home, and Youssef grew up with the support of his mother and family. His mother later remarried, and her second husband eventually became a priest. The faith of his home, the prayers of his village, and the example of two maternal uncles who had chosen the hermit's life helped shape his spiritual interests. As a boy, Youssef cared for the family’s animals and often withdrew to a quiet grotto to pray. That place is remembered today as the Grotto of Saint Charbel. He learned to love silence, prayer and a life centred on God from an early age.\n\nIn 1851, at the age of twenty-three, Youssef left Bqaa Kafra and entered the Lebanese Maronite Order at the Monastery of Our Lady of Mayfouq. He did so with a firm desire to dedicate his whole life to God. He later continued his novitiate at the Monastery of Saint Maron in Annaya. On 1 November 1853, he made his monastic profession and took the name Charbel, after an early Christian martyr of the Church of Antioch. His formation continued at the Monastery of Saints Cyprian and Justina in Kfifan, where he studied philosophy and theology in preparation for the priesthood. One of the monks who deeply influenced him was Saint Nimatullah al-Hardini. Charbel admired his teacher’s fidelity to prayer, humility, obedience and the monastic rule. Their years together helped form the quiet, disciplined spirituality for which Charbel later became known.\n\nOn 23 July 1859, Charbel was ordained a priest at Bkerké. He served for a short time at the Monastery of Saint James in Douma before returning to the Monastery of Saint Maron in Annaya. For sixteen years, from 1859 to 1875, he lived as a monk in the community there. His days were shaped by the celebration of the Eucharist, the Divine Office, personal prayer, study and manual work. He was not known for seeking attention or recognition. Instead, he tried to carry out ordinary duties faithfully, treating obedience and humility as important parts of his vocation. A well-known account from this period is the story of the lamp that was filled with water instead of oil and nevertheless gave light. The episode is preserved in the religious tradition surrounding his life and is associated with the permission he eventually received to become a hermit.\n\nCharbel had long desired a more solitary life of prayer. After requesting permission from his superiors, he entered the Hermitage of Saints Peter and Paul, belonging to the monastery of Annaya, on 15 February 1875. He remained there for the next twenty-three years, until his death. His life followed the rhythm of the hermitage: prayer, the celebration of Mass, periods of contemplation, reading, simple meals and work. He embraced poverty and simplicity, kept silence, and sought to place God at the centre of every part of his day. His devotion to the Eucharist was especially deep. He celebrated Mass with great reverence and prepared for it through long hours of prayer. He also had a strong devotion to the Virgin Mary. Although he lived apart from the wider community, people gradually came to know of his holiness. Visitors sought his blessing, spiritual counsel and prayers. Accounts of favours and healings attributed to his intercession began to circulate, and the hermitage became a place of pilgrimage. These accounts belong to the Church's devotional tradition and are presented as reports of people who asked for his prayers.\n\nIn December 1898, while celebrating Mass, Charbel suffered a sudden illness at the altar. He was carried to his room, where he remained seriously ill for eight days. Accounts of his final days remember him continuing to pray the words of the Eucharistic liturgy. He died on 24 December 1898, on the eve of Christmas, at the age of seventy. He was buried in the monastery cemetery at Annaya. Soon after his burial, reports spread of a mysterious light seen near his grave, and pilgrims began to visit and pray there. In 1899, his tomb was opened with ecclesiastical permission, and the condition of his remains became the subject of further investigation. Over the following decades, the Church examined reports connected with his tomb and with healings attributed to his intercession. These events helped draw pilgrims from Lebanon and from many other countries.\n\nThe Church formally advanced Charbel’s cause for canonisation during the twentieth century. Pope Paul VI declared him Blessed on 5 December 1965, during the closing period of the Second Vatican Council. On 9 October 1977, the same pope canonised him in Saint Peter’s Basilica in Rome. Saint Charbel became one of Lebanon’s best-loved saints and an internationally recognised witness to Maronite monastic spirituality. His feast is celebrated on 24 July in the Latin Catholic calendar, while his death is also remembered on 24 December in the Maronite tradition. The monastery of Saint Maron in Annaya and the nearby hermitage remain major places of pilgrimage. People from different countries and Christian traditions continue to visit, pray and ask for his intercession. His story is not only a story of extraordinary reports after death: it is also the story of a Lebanese village boy who chose a life of prayer, a monk formed by the Maronite tradition, a priest devoted to the Eucharist, and a hermit who sought to live every day with humility, silence and faith.",storyAr:"وُلد القديس شربل مخلوف باسم يوسف أنطون مخلوف في 8 أيار 1828 في بقاعكفرا، القرية الجبلية الواقعة في شمال لبنان. كان أصغر أبناء أنطون زعرور مخلوف وبريجيت يعقوب الشدياق. عاشت عائلته حياة بسيطة وتميّزت بإيمانها المسيحي العميق. نال يوسف سرّ العماد في كنيسة سيّدة بقاعكفرا في 16 أيار 1828. توفّي والده وهو لا يزال طفلًا صغيرًا، فنشأ في كنف والدته وعائلته. تزوّجت والدته لاحقًا، وأصبح زوجها الثاني كاهنًا. وقد ترك إيمان البيت وصلوات القرية ومثال خاليه اللذين اختارا الحياة النسكيّة أثرًا كبيرًا في تكوينه الروحي. في طفولته، كان يوسف يساعد في رعاية مواشي العائلة، وكان يبتعد أحيانًا إلى مغارة هادئة ليصلّي. ويُعرف هذا المكان اليوم باسم مغارة القديس شربل. منذ صغره أحبّ الصلاة والصمت والحياة التي يكون الله في مركزها.\n\nفي سنة 1851، وكان في الثالثة والعشرين من عمره، غادر يوسف بقاعكفرا ودخل الرهبنة اللبنانية المارونية في دير سيّدة ميفوق، راغبًا في تكريس حياته كلّها لله. ثم تابع فترة الابتداء في دير مار مارون في عنّايا. وفي الأول من تشرين الثاني 1853، أبرز نذوره الرهبانية واتخذ اسم شربل، تيمّنًا بأحد شهداء الكنيسة الأنطاكية في القرون المسيحية الأولى. تابع تنشئته الرهبانية في دير القديسين قبريانوس ويوستينا في كفيفان، حيث درس الفلسفة واللاهوت استعدادًا للكهنوت. وكان القديس نعمة الله الحرديني من أبرز الرهبان الذين تركوا أثرًا في حياته. فقد تأثّر شربل بتواضعه وأمانته للصلاة والطاعة والقاعدة الرهبانية. وساعدته هذه التنشئة على ترسيخ الروحانية الهادئة والمنضبطة التي عُرف بها لاحقًا.\n\nفي 23 تموز 1859، رُسم شربل كاهنًا في بكركي. خدم فترة قصيرة في دير مار يعقوب في دوما، ثم عاد إلى دير مار مارون في عنّايا. عاش هناك ستة عشر عامًا، من 1859 حتى 1875، راهبًا بين إخوته. وكان يومه منظّمًا حول الاحتفال بالقداس الإلهي، والصلاة الليتورجية، والتأمل، والقراءة والعمل اليدوي. لم يكن يسعى إلى الظهور أو نيل المديح، بل كان يحاول أن يقوم بالواجبات اليومية بأمانة، معتبرًا الطاعة والتواضع جزءًا أساسيًا من دعوته. ومن الروايات المشهورة عن تلك المرحلة قصة السراج الذي مُلئ بالماء بدل الزيت، ومع ذلك أضاء. وقد حفظ التقليد الرهباني هذه الرواية وربطها بطلب شربل الانتقال إلى الحياة النسكية.\n\nكان شربل يرغب منذ زمن في التفرّغ لحياة أكثر عزلة وصلاة. وبعد أن طلب الإذن من رؤسائه، دخل محبسة القديسين بطرس وبولس التابعة لدير عنّايا في 15 شباط 1875. وبقي فيها ثلاثة وعشرين عامًا، حتى وفاته. اتّبعت حياته إيقاع المحبسة: الصلاة، والقداس، والتأمل، والقراءة، والطعام البسيط والعمل. اختار الفقر والبساطة، وحافظ على الصمت، وسعى إلى جعل الله محور كل تفاصيل يومه. وكان تعبّده للقربان المقدّس عميقًا بصورة خاصة؛ فكان يحتفل بالقداس بخشوع كبير ويستعدّ له بساعات طويلة من الصلاة. كما كانت له محبة كبيرة للعذراء مريم. ومع أنه عاش بعيدًا عن الحياة اليومية للناس، انتشرت أخبار قداسته تدريجيًا، وصار الزوار يقصدونه لطلب البركة والإرشاد الروحي وصلاته. وبدأت تنتشر شهادات عن نعم وشفاءات ينسبها أصحابها إلى شفاعته، فتحوّلت المحبسة إلى مقصد للحج. وتُعرض هذه الأمور هنا بوصفها شهادات وروايات إيمانية لأشخاص طلبوا صلاته.\n\nفي كانون الأول 1898، وبينما كان شربل يحتفل بالقداس الإلهي، أصابته وعكة صحية مفاجئة عند المذبح. نُقل إلى غرفته وبقي مريضًا مدة ثمانية أيام. وتذكر الروايات عن أيامه الأخيرة أنه ظلّ يردّد صلوات الليتورجيا الإفخارستية. رقد بالرب في 24 كانون الأول 1898، عشية عيد الميلاد، عن عمر سبعين عامًا. ودُفن في مدافن الدير في عنّايا. وبعد دفنه بوقت قصير، انتشرت شهادات عن نور شوهد قرب قبره، وبدأ المؤمنون يقصدون المكان للصلاة. وفي سنة 1899، فُتح القبر بإذن كنسي، وأصبحت حالة رفاته موضع متابعة وتحقيق. وخلال العقود التالية، درست الكنيسة الشهادات المرتبطة بالقبر وبالشفاءات المنسوبة إلى شفاعته. وأسهمت هذه الأخبار في قدوم الحجاج من لبنان وبلدان كثيرة.\n\nتابعت الكنيسة رسميًا دعوى تطويب شربل وإعلانه قديسًا خلال القرن العشرين. ففي 5 كانون الأول 1965، أعلنه البابا بولس السادس طوباويًا، في ختام أعمال المجمع الفاتيكاني الثاني. ثم أعلنه قديسًا في 9 تشرين الأول 1977 في بازيليك القديس بطرس في روما. وأصبح القديس شربل من أكثر قديسي لبنان محبةً وإكرامًا، وشاهدًا معروفًا على روحانية الرهبنة المارونية. يُحتفل بعيده في 24 تموز في التقويم الكاثوليكي اللاتيني، كما تُذكر ذكرى رقاده في 24 كانون الأول في التقليد الماروني. ولا يزال دير مار مارون في عنّايا والمحبسة القريبة منه مقصدين أساسيين للحجاج. ويأتي الناس من بلدان وتقاليد مسيحية مختلفة للصلاة وطلب شفاعته. وليست قصته مجرد روايات عن أحداث بعد وفاته؛ إنها أيضًا قصة فتى لبناني اختار الصلاة، وراهب تكوّن في التراث الماروني، وكاهن أحبّ القربان المقدّس، وناسك سعى إلى عيش التواضع والصمت والإيمان في كل يوم من حياته."},
    {en:"Estephan El Douaihy",ar:"البطريرك المكرّم إسطفان الدويهي",letter:"E",status:"Blessed · Maronite patriarch · beatified 2024",place:"Ehden · إهدن",years:"1630–1704",storyEn:"Born in Ehden in 1630, Estephan El Douaihy became Maronite patriarch and one of the Church's great historians and scholars. He worked to preserve the liturgy, music, manuscripts and memory of the Maronite people through a difficult period. A miracle attributed to his intercession was recognised in 2024, and he was beatified in Bkerké on 2 August 2024. He is Blessed, not canonised.",storyAr:"وُلد إسطفان الدويهي في إهدن سنة 1630، وأصبح بطريركًا مارونيًا ومن أبرز مؤرّخي الكنيسة وعلمائها. عمل على حفظ الليتورجيا والموسيقى والمخطوطات وذاكرة الشعب الماروني في مرحلة صعبة. أُعلن طوباويًا في بكركي في 2 آب 2024 بعد الاعتراف بأعجوبة منسوبة إلى شفاعته."},
    {en:"Ignatius Maloyan",ar:"القديس إغناطيوس مالويان",letter:"I",status:"Canonized saint · Armenian Catholic archbishop and martyr · 2025",place:"Mardin; formed in Lebanon · ماردين ولبنان",years:"1869–1915",storyEn:"Ignatius Maloyan was an Armenian Catholic archbishop whose priestly formation included study at Bzommar in Lebanon. During the Armenian genocide, he encouraged his people to remain faithful and was martyred in 1915. Pope John Paul II beatified him in 2001, and Pope Leo XIV canonized him on 19 October 2025.",storyAr:"كان إغناطيوس مالويان رئيس أساقفة أرمنيًا كاثوليكيًا، وتلقّى تكوينه الكهنوتي في دير بزمار في لبنان. خلال الإبادة الأرمنية، شجّع أبناء رعيته على الثبات في الإيمان واستشهد سنة 1915. أعلنه البابا يوحنا بولس الثاني طوباويًا سنة 2001، ثم أعلنه البابا لاون الرابع عشر قديسًا في 19 تشرين الأول 2025."},
    {en:"Nimatullah Al-Hardini",ar:"القديس نعمة الله كسّاب الحرديني",letter:"N",status:"Canonized saint · 2004",place:"Hardine & Kfifan · حردين وكفيفان",years:"1808–1858",storyEn:"Youssef Kassab was born in Hardine in 1808. He joined the Lebanese Maronite Order in 1828, took the name Nimatullah, and became a priest, teacher and spiritual guide at Kfifan. Known for his devotion to the Eucharist and care for his fellow monks, he died in 1858. Pope John Paul II canonized him in 2004.",storyAr:"وُلد يوسف كسّاب في حردين سنة 1808. انضمّ إلى الرهبنة اللبنانية المارونية سنة 1828 واتخذ اسم نعمة الله، وصار كاهنًا ومعلّمًا ومرشدًا روحيًا في كفيفان. عُرف بتعبّده للقربان المقدّس واهتمامه بإخوته الرهبان. توفّي سنة 1858 وأعلنه البابا يوحنا بولس الثاني قديسًا سنة 2004."},
    {en:"Rafqa Pietra Choboq Ar-Rayès",ar:"القديسة رفقا بيطرا الشوبق الريّس",letter:"R",status:"Canonized saint · 2001",place:"Himlaya & Jrabta · حماليا وجربتا",years:"1832–1914",storyEn:"Rafqa Pietra Choboq Ar-Rayès was born Boutrossieh Rayess on 29 June 1832 in Himlaya, in the northern Metn region of Lebanon. She was the only child of Mourad Saber el-Choboq el-Rayess and Rafqa Gemayel. Her parents taught her to love God and to pray each day. Her mother died when Boutrossieh was seven, a deep loss in her childhood. When her father later faced financial hardship, he sent her to Damascus, where she worked in a household for several years before returning to Lebanon. As she grew older, she felt drawn to religious life. In 1859 she entered the Congregation of the Mariamettes at the convent of Our Lady of Deliverance in Bikfaya and received the religious habit in 1861, taking her first vows the following year. She served in the congregation’s schools and communities, including work at the Jesuit seminary in Ghazir, teaching catechism in Deir el-Qamar, and educating girls in Byblos and Maad. During the violence in Lebanon in 1860, she is remembered for protecting a child by hiding him beneath her robe. In 1871, after a crisis led to the dissolution of the Mariamette congregation, Rafqa prayed for guidance. According to her biography, she experienced a renewed sense of her vocation and entered the Lebanese Maronite Order. She received the habit at the Monastery of Saint Simon al-Qarn in Aito on 12 July 1871 and made her solemn profession on 25 August 1872. She spent twenty-six years there, known for fidelity to the monastic rule, prayer, silence and service. On the first Sunday of October 1885, she prayed to share in the suffering of Christ’s Passion. Soon afterward she began to experience severe pain, first in her head and eyes. Medical treatment did not restore her sight; she gradually lost the use of both eyes and endured further physical suffering. In 1897 she moved with other nuns to the Monastery of Saint Joseph al-Dahr in Jrabta, near Batroun. Even as her health declined, she continued to pray, give thanks and use her hands for simple work such as knitting clothes for others. She died at Jrabta on 23 March 1914 and was buried in the monastery cemetery. Her tomb became a place of prayer and pilgrimage, and reports of favours attributed to her intercession led to the Church’s investigation of her cause. Pope John Paul II declared her Venerable in 1982, beatified her on 17 November 1985, and canonised her on 10 June 2001. Saint Rafqa is especially cherished in Lebanon as a Maronite nun whose life joined education, service, contemplative prayer and patient faith through suffering.",storyAr:"وُلدت رفقا بيطرا الشوبق الريّس، واسمها في المعمودية بطرسّية، في 29 حزيران 1832 في حماليا بمنطقة المتن الشمالي في لبنان. كانت الابنة الوحيدة لمراد صابر الشوبق الريّس ورفقا الجميل. ربّاها والداها على محبة الله والصلاة اليومية، لكن والدتها توفيت عندما كانت في السابعة من عمرها. وبعد أن واجه والدها ضائقة مالية، أرسلها إلى دمشق حيث عملت في أحد البيوت عدة سنوات قبل أن تعود إلى لبنان. ومع نموّها، شعرت بدعوة إلى الحياة الرهبانية. سنة 1859 دخلت جمعية المريمات في دير سيدة النجاة في بكفيا، ولبست الثوب الرهباني في 19 آذار 1861، ثم أبرزت نذورها الأولى في السنة التالية. خدمت في مدارس وجماعات الجمعية، ومنها العمل في إكليريكية الآباء اليسوعيين في غزير، وتعليم التعليم المسيحي في دير القمر، وتربية الفتيات في جبيل ومعاد. وخلال أحداث العنف في لبنان سنة 1860، يُذكر أنها خاطرت بنفسها لحماية طفل أخفته تحت ثوبها. سنة 1871، وبعد أزمة أدّت إلى حل جمعية المريمات، صلّت رفقا طالبةً إرشاد الله. ووفقًا لسيرتها، تجدّدت لديها الدعوة إلى الحياة الرهبانية، فدخلت الرهبنة اللبنانية المارونية. لبست الثوب في دير مار سمعان القرن في أيطو في 12 تموز 1871، وأبرزت نذورها الاحتفالية في 25 آب 1872. أمضت هناك ستة وعشرين عامًا عُرفت خلالها بالأمانة للقوانين الرهبانية والصلاة والصمت والخدمة. في الأحد الأول من تشرين الأول 1885، صلّت طالبةً أن تشارك في آلام المسيح. وبعد ذلك بوقت قصير بدأت تعاني أوجاعًا شديدة في رأسها وعينيها. ولم تنجح العلاجات الطبية في إعادة بصرها؛ ففقدت تدريجيًا النظر في عينيها، وعانت آلامًا جسدية أخرى. سنة 1897 انتقلت مع راهبات أخريات إلى دير مار يوسف الضهر في جربتا قرب البترون. وعلى الرغم من تدهور صحتها، واصلت الصلاة والشكر، واستعملت يديها في أعمال بسيطة كحياكة الثياب للآخرين. رقدت في جربتا في 23 آذار 1914 ودُفنت في مقبرة الدير. وصار ضريحها مقصدًا للصلاة والحج، وأدّت النعم المنسوبة إلى شفاعتها إلى فتح التحقيق الكنسي في دعوى قداستها. أعلنها البابا يوحنا بولس الثاني مكرّمة سنة 1982، وطوباوية في 17 تشرين الثاني 1985، وقديسة في 10 حزيران 2001. وتبقى القديسة رفقا عزيزة على اللبنانيين بوصفها راهبة مارونية جمعت في حياتها بين التعليم والخدمة والصلاة التأملية والإيمان الصبور وسط الألم."},
    {en:"Estephan Nehme",ar:"الطوباوي إسطفان نعمه",letter:"S",status:"Blessed · 2010",place:"Lehfed · لحفد",years:"1889–1938",storyEn:"Estephan Nehme was born in Lehfed in 1889 and joined the Lebanese Maronite Order as a monk. He was known for a quiet life of prayer, humility and faithful work. He died in 1938 and was beatified by Pope Benedict XVI in 2010.",storyAr:"وُلد إسطفان نعمه في لحفد سنة 1889 وانضمّ إلى الرهبنة اللبنانية المارونية. عُرف بحياة هادئة من الصلاة والتواضع والعمل الأمين. توفّي سنة 1938 وأعلنه البابا بندكتس السادس عشر طوباويًا سنة 2010."},
    {en:"Leonard Melki",ar:"الطوباوي يوسف حبيب ملكي",letter:"L",status:"Blessed · Martyr",place:"Baskinta · بسكنتا",years:"1881–1915",storyEn:"Youssef Habib Melki, known as Leonard, was a Capuchin priest born in Baskinta. He served communities in the Ottoman Empire and was killed during the persecution of Christians in 1915. He was beatified in 2022 together with Thomas Saleh.",storyAr:"وُلد يوسف حبيب ملكي، المعروف بالأب ليونار، في بسكنتا وكان كاهنًا كبوشيًا. خدم جماعات مسيحية في الدولة العثمانية واستشهد خلال اضطهاد المسيحيين سنة 1915. أُعلن طوباويًا سنة 2022 مع الأب توما صالح."},
    {en:"Thomas Saleh",ar:"الطوباوي توما صالح",letter:"T",status:"Blessed · Martyr",place:"Baabdat · بعبدات",years:"1879–1917",storyEn:"Thomas Saleh was a Lebanese Capuchin priest from Baabdat. His ministry brought him to the region of present-day Turkey, where he endured imprisonment and persecution and died in 1917. He was beatified in 2022 with Leonard Melki.",storyAr:"كان توما صالح كاهنًا كبوشيًا لبنانيًا من بعبدات. قادته خدمته إلى منطقة تركيا الحالية، حيث تعرّض للسجن والاضطهاد وتوفّي سنة 1917. أُعلن طوباويًا سنة 2022 مع ليونار ملكي."},
    {en:"The Massabki Brothers",ar:"الإخوة الشهداء المسابكي",letter:"M",status:"Canonized saints · 2024",place:"Damascus; Maronite family from Lebanon · دمشق",years:"Martyred 1860",storyEn:"Francis, Abdel Moati and Raphael Massabki were three Maronite brothers from a Lebanese family living in Damascus. During the persecution of Christians in 1860, they refused to abandon their faith and were killed. Pope Francis canonized the Massabki brothers in October 2024.",storyAr:"كان فرنسيس وعبد المعطي ورفائيل المسابكي ثلاثة إخوة موارنة من عائلة لبنانية عاشت في دمشق. خلال اضطهاد المسيحيين سنة 1860، رفضوا التخلّي عن إيمانهم واستشهدوا. أعلن البابا فرنسيس الإخوة المسابكيين قديسين في تشرين الأول 2024."},
    {en:"Maron",ar:"القديس مارون",letter:"M",status:"Saint · Father of the Maronite tradition",place:"Syrian region; spiritual heritage of Lebanon",years:"Died c. 410",storyEn:"Maron was an ascetic priest and hermit whose prayer and way of life attracted disciples. The community that grew around his spiritual tradition became known as the Maronites. Although he lived before modern national borders, his legacy is deeply rooted in the history of the Maronite Church in Lebanon.",storyAr:"كان مارون كاهنًا وناسكًا عاش حياة نسك وصلاة، واجتمع حوله تلاميذ تأثّروا بروحانيته. ونمت من هذا التقليد الجماعة التي عُرفت لاحقًا بالموارنة. ورغم أنه عاش قبل نشوء الحدود الوطنية الحديثة، فإن إرثه متجذّر في تاريخ الكنيسة المارونية في لبنان."}
  ];
  entries.push(...[{"en":"John Mark","ar":"القديس يوحنا مرقس","letter":"J","status":"Saint · Bishop","place":"Lebanon · early Church","years":"1st century","storyEn":"Early Christian tradition associates John Mark with the apostolic Church and the Gospel bearing his name. The Lebanese catalogue lists him among saints connected with the country; details of his life are drawn from early Christian tradition.","storyAr":"يربط التقليد المسيحيّ القديم يوحنا مرقس بالكنيسة الرسوليّة وبالإنجيل الذي يحمل اسمه. وتُدرجه لوائح القديسين المرتبطين بلبنان، فيما تستند تفاصيل حياته إلى التقليد المسيحيّ الأوّل."},{"en":"Nilus of Egypt","ar":"القديس نيلس","letter":"N","status":"Saint · Bishop","place":"Lebanon · ancient martyrdom tradition","years":"Died c. 303","storyEn":"Nilus is remembered in early Christian martyrology among bishops associated with persecutions in the eastern Roman provinces. The surviving details are limited, so his entry is kept brief and identified as an early tradition.","storyAr":"يُذكر نيلس في سنكسارات الشهداء المسيحيّين الأوائل ضمن الأساقفة المرتبطين باضطهادات المقاطعات الشرقيّة للإمبراطوريّة الرومانيّة. والمعلومات التاريخيّة المتبقيّة عنه محدودة."},{"en":"Peleus","ar":"القديس بيليوس","letter":"P","status":"Saint · Bishop","place":"Lebanon · ancient martyrdom tradition","years":"Died c. 303","storyEn":"Peleus is listed in early Christian martyrologies among bishops who suffered during the persecutions under Diocletian. His commemoration is preserved in the Church's ancient memory.","storyAr":"يَرِد اسم بيليوس في السنكسارات المسيحيّة القديمة بين الأساقفة الذين استشهدوا في اضطهادات دقلديانوس. وقد حُفظ تذكاره في الذاكرة الكنسيّة القديمة."},{"en":"Silvanus","ar":"القديس سيلفانوس","letter":"S","status":"Saint · Bishop","place":"Lebanon · ancient tradition","years":"Died c. 303","storyEn":"Silvanus is honoured in the ancient Christian tradition as a bishop and martyr. Historical details are sparse, and later calendars preserve his name among witnesses of the early Church.","storyAr":"يُكرَّم سيلفانوس في التقليد المسيحيّ القديم كأسقف وشهيد. وتبقى تفاصيل حياته قليلة، فيما تحفظه التقاويم الكنسيّة بين شهود الكنيسة الأولى."},{"en":"Tyrannio of Tyre","ar":"القديس تيرانيون","letter":"T","status":"Saint · Bishop and martyr","place":"Tyre · صور","years":"Died c. 311","storyEn":"Tyrannio is associated in Christian martyrologies with the early Church of Tyre and the persecutions of the third and fourth centuries. He is remembered as a bishop who bore witness to his faith.","storyAr":"يرتبط اسم تيرانيون في السنكسارات المسيحيّة بكنيسة صور في القرنين الثالث والرابع. ويُذكر كأسقف شهد لإيمانه في زمن الاضطهاد."},{"en":"Zenobius of Sidon","ar":"القديس زينوبوس","letter":"Z","status":"Saint · Priest and martyr","place":"Sidon · صيدا","years":"Early 4th century","storyEn":"Zenobius is remembered in eastern Christian tradition as a priest and martyr connected with the Phoenician coast. The historical record is brief, and traditions differ on some details.","storyAr":"يُذكر زينوبius في التقليد المسيحيّ الشرقيّ كاهنًا وشهيدًا مرتبطًا بالساحل الفينيقيّ. والمعلومات التاريخيّة عنه موجزة وتختلف بعض الروايات في تفاصيلها."},{"en":"Vulpian of Tyre","ar":"القديس فولبيانوس","letter":"V","status":"Saint · Martyr","place":"Tyre · صور","years":"Died c. 304","storyEn":"Vulpian is named in ancient martyrologies as a Christian martyr of Tyre during the persecution under Diocletian. His memory belongs to the early Christian history of the Lebanese coast.","storyAr":"يَرِد فولبيانوس في السنكسارات القديمة كشهيد مسيحيّ من صور في زمن اضطهاد دقلديانوس. ويرتبط تذكاره بتاريخ المسيحيّة الأولى على الساحل اللبنانيّ."},{"en":"Cyril of Heliopolis","ar":"القديس كيرلس","letter":"C","status":"Saint · Deacon and martyr","place":"Lebanon · ancient tradition","years":"Died c. 362","storyEn":"Cyril is recorded in eastern Christian calendars among the martyrs of the fourth century. The details of his ministry and death are preserved only in brief martyrological notices.","storyAr":"يُسجَّل كيرلس في التقاويم المسيحيّة الشرقيّة بين شهداء القرن الرابع. ولم تصلنا عن خدمته واستشهاده سوى إشارات موجزة في السنكسارات."},{"en":"Dorotheus","ar":"القديس دوروثاوس","letter":"D","status":"Saint · Bishop","place":"Lebanon · ancient tradition","years":"Died c. 363","storyEn":"Dorotheus appears in ancient Christian lists of bishops and martyrs connected with the eastern Mediterranean. Because accounts are fragmentary, his biography is presented cautiously.","storyAr":"يظهر دوروثاوس في لوائح مسيحيّة قديمة لأساقفة وشهداء ارتبطوا بشرق المتوسّط. ولأن الروايات مجتزأة، تُعرض سيرته بحذر."},{"en":"Nerses I the Great","ar":"القديس نرسيس الكبير","letter":"N","status":"Saint · Armenian bishop","place":"Armenia · Armenian Christian heritage","years":"4th century","storyEn":"Nerses I was a major Armenian Church leader who promoted Christian teaching, charitable institutions and care for the poor. His story is included as part of the wider Christian heritage of the region, not as a Lebanese-born saint.","storyAr":"كان نرسيس الأوّل من أبرز قادة الكنيسة الأرمنيّة، وعمل على نشر التعليم المسيحيّ وإنشاء مؤسّسات خيريّة والعناية بالفقراء. ندرجه ضمن التراث المسيحيّ الأوسع في المنطقة، لا كقديس مولود في لبنان."},{"en":"Frumentius","ar":"القديس فرومنتيوس","letter":"F","status":"Saint · Bishop","place":"Lebanon connection in ancient tradition","years":"4th century","storyEn":"Frumentius is remembered as the missionary bishop who helped establish Christianity in the Kingdom of Aksum, in present-day Ethiopia and Eritrea. Some lists associate his early life with the Levant; the strongest part of his legacy is his Ethiopian mission.","storyAr":"يُذكر فرومنتيوس كأسقف مرسل ساهم في ترسيخ المسيحيّة في مملكة أكسوم، في إثيوبيا وإريتريا حاليًا. تربط بعض اللوائح بدايات حياته بالمشرق، أمّا أبرز إرثه فهو رسالته في إثيوبيا."},{"en":"Leontius","ar":"القديس ليونتيوس","letter":"L","status":"Saint · Martyr","place":"Lebanon · early Christian tradition","years":"4th century","storyEn":"Leontius is a name preserved in early Christian martyrologies associated with the eastern Mediterranean. As the surviving biographical record is uncertain, this entry distinguishes traditional veneration from documented biography.","storyAr":"ليونتيوس اسم محفوظ في السنكسارات المسيحيّة الأولى المرتبطة بشرق المتوسّط. وبما أنّ المعلومات السيريّة غير مؤكّدة، تميّز هذه البطاقة بين الإكرام التقليديّ والسيرة الموثّقة."},{"en":"Nonnus of Edessa","ar":"القديس نونّوس","letter":"N","status":"Saint · Bishop","place":"Eastern Christian tradition","years":"5th century","storyEn":"Nonnus is remembered in eastern Christian tradition as a bishop associated with the spiritual history of Edessa. Accounts of his life are preserved mainly through later ecclesiastical tradition.","storyAr":"يُذكر نونّوس في التقليد المسيحيّ الشرقيّ كأسقف ارتبط بالتاريخ الروحيّ لمدينة الرها. وقد حُفظت أخبار حياته أساسًا في التقاليد الكنسيّة اللاحقة."},{"en":"Elias Hoayek","ar":"البطريرك الطوباوي إلياس الحويّك","letter":"E","status":"Blessed · Maronite patriarch","place":"Helta · الحيطة","years":"1843–1931","storyEn":"Elias Hoayek was born in Helta in North Lebanon in 1843 and served as Maronite patriarch from 1899 to 1931. He helped found the Congregation of the Maronite Sisters of the Holy Family, cared for people facing hunger and displacement during World War I, and played a major role in the events surrounding the proclamation of Greater Lebanon in 1920. He was beatified in Dimane on 25 July 2026 and is honoured as Blessed Elias Hoayek, not yet a canonised saint.","storyAr":"وُلد إلياس الحويّك في الحيطة في شمال لبنان سنة 1843، وخدم بطريركًا للموارنة بين 1899 و1931. ساهم في تأسيس جمعيّة راهبات العائلة المقدّسة المارونيّات، واهتمّ بالجائعين والمهجّرين خلال الحرب العالميّة الأولى، وكان له دور بارز في الأحداث التي رافقت إعلان دولة لبنان الكبير سنة 1920. أُعلن طوباويًا في الديمان في 25 تموز 2026، ويُكرَّم بصفة الطوباوي إلياس الحويّك، ولم يُعلن قديسًا بعد."},{"en":"Yaqub Haddad","ar":"الطوباوي يعقوب الكبّوشي","letter":"Y","status":"Blessed · Capuchin priest","place":"Ghazeer · غزير","years":"1875–1954","storyEn":"Khalil Haddad, known as Father Yaqub, was a Lebanese Capuchin priest who founded the Franciscan Sisters of the Cross. He devoted his ministry to the poor, the sick and people in need, and was beatified in 2008.","storyAr":"كان خليل حدّاد، المعروف بالأب يعقوب، كاهنًا كبّوشيًا لبنانيًا أسّس راهبات الصليب الفرنسيسكانيّات. كرّس خدمته للفقراء والمرضى والمحتاجين، وأُعلن طوباويًا سنة 2008."},{"en":"Béchara Abou Mrad","ar":"الأب بشارة أبو مراد","letter":"B","status":"Servant of God · Melkite priest","place":"Zahlé · زحلة","years":"1853–1930","storyEn":"Béchara Abou Mrad was a Melkite priest from Lebanon remembered for his pastoral service and spiritual life. His cause has been introduced, but he should be described as a Servant of God rather than a blessed or canonised saint.","storyAr":"كان بشارة أبو مراد كاهنًا ملكيًا من لبنان، عُرف بخدمته الرعويّة وحياته الروحيّة. وقد فُتحت قضيّة تطويبه، لكنّ اللقب الدقيق له هو خادم الله، لا طوباوي أو قديس مُعلن."},{"en":"Francis of Assisi","ar":"القديس فرنسيس الأسيزي","letter":"F","status":"Saint · Founder","place":"Assisi, Italy","years":"1181/82–1226","storyEn":"Francis gave up wealth to live simply, serve people who were poor and care for creation. He founded the Franciscan movement and became one of Christianity's best-known witnesses to humility and peace.","storyAr":"تخلّى فرنسيس عن الغنى ليعيش ببساطة ويخدم الفقراء ويعتني بالخليقة. أسّس الحركة الفرنسيسكانيّة وأصبح من أشهر شهود التواضع والسلام في المسيحيّة."},{"en":"Clare of Assisi","ar":"القديسة كلارا الأسيزيّة","letter":"C","status":"Saint · Founder","place":"Assisi, Italy","years":"1194–1253","storyEn":"Clare followed the example of Francis and founded the Poor Clares. She chose a life of prayer, simplicity and community, becoming a model of courage and devotion.","storyAr":"اقتدت كلارا بفرنسيس وأسّست جماعة الكلاريسات الفقيرات. اختارت حياة الصلاة والبساطة والأخوّة، وأصبحت مثالًا للشجاعة والتعبّد."},{"en":"Augustine of Hippo","ar":"القديس أوغسطينوس","letter":"A","status":"Saint · Bishop and Doctor","place":"Hippo, North Africa","years":"354–430","storyEn":"After a restless search for truth, Augustine became a Christian and later bishop of Hippo. His writings, especially Confessions, shaped Christian thought for centuries.","storyAr":"بعد بحث طويل عن الحقيقة، اعتنق أوغسطينوس المسيحيّة وأصبح أسقف هيبّون. أثّرت كتاباته، ولا سيّما الاعترافات، في الفكر المسيحيّ قرونًا طويلة."},{"en":"Monica","ar":"القديسة مونيكا","letter":"M","status":"Saint · Mother","place":"North Africa","years":"c. 331–387","storyEn":"Monica is remembered for her patient faith and persistent prayer for her family, especially her son Augustine. Her story is often shared as an example of hope and steadfast love.","storyAr":"تُذكر مونيكا لإيمانها الصبور وصلاتها الدائمة من أجل عائلتها، ولا سيّما ابنها أوغسطينوس. وتُروى قصّتها مثالًا للرجاء والمحبّة الثابتة."},{"en":"Benedict of Nursia","ar":"القديس بندكتس","letter":"B","status":"Saint · Founder","place":"Nursia, Italy","years":"c. 480–547","storyEn":"Benedict shaped western monastic life through a rule that balances prayer, work, hospitality and community. His Rule became a foundation for many monasteries.","storyAr":"ساهم بندكتس في تشكيل الحياة الرهبانيّة الغربيّة من خلال قاعدة توازن بين الصلاة والعمل والضيافة والحياة المشتركة. وأصبحت قاعدته أساسًا لأديرة كثيرة."},{"en":"Anthony the Great","ar":"القديس أنطونيوس الكبير (مار أنطونيوس الكبير)","letter":"A","status":"Saint · Father of Monasticism","place":"Egypt · deeply venerated in Lebanon · مصر ومكرّم في لبنان","years":"c. 251–356","storyEn":"Anthony, known throughout the Christian East as Mar Antonios the Great, was born in Egypt in the third century. After hearing the Gospel call to leave his possessions and follow Christ, he gave away his inheritance and withdrew to a life of prayer in the desert. Other Christians came to learn from his discipline, simplicity and spiritual wisdom, and his example helped shape the beginnings of Christian monasticism. Athanasius of Alexandria preserved an influential account of his life, which introduced Anthony’s witness to Christians far beyond Egypt. He is not Lebanese by birth, but devotion to Mar Antonios is deeply rooted in Lebanon, where churches, monasteries and families honour him as one of the great fathers of monastic life.","storyAr":"أنطونيوس، المعروف في الشرق المسيحي باسم مار أنطونيوس الكبير، وُلد في مصر في القرن الثالث. وبعد أن تأثّر بدعوة الإنجيل إلى ترك الممتلكات واتباع المسيح، وزّع ميراثه وانصرف إلى حياة الصلاة والنسك في الصحراء. وجاء مسيحيون كثيرون ليتعلّموا من انضباطه وبساطته وحكمته الروحية، وأسهم مثاله في نشأة الرهبنة المسيحية. وقد حفظ أثناسيوس الإسكندري سيرة مؤثرة عنه، عرّفت المؤمنين في بلدان كثيرة بشهادته. لم يولد أنطونيوس في لبنان، لكن إكرامه متجذّر في الحياة الكنسية اللبنانية، حيث تحمل كنائس وأديرة وعائلات كثيرة اسمه وتكرّمه أبًا من آباء الحياة الرهبانية."},{"en":"Athanasius of Alexandria","ar":"القديس أثناسيوس","letter":"A","status":"Saint · Bishop and Doctor","place":"Alexandria, Egypt","years":"c. 296–373","storyEn":"Athanasius defended the Christian teaching about Christ during the Arian controversy and served as bishop of Alexandria. His writings helped shape the Church's understanding of the Incarnation.","storyAr":"دافع أثناسيوس عن التعليم المسيحيّ حول شخص المسيح خلال الجدل الآريوسيّ، وخدم أسقفًا للإسكندريّة. وأسهمت كتاباته في صياغة فهم الكنيسة للتجسّد."},{"en":"Basil the Great","ar":"القديس باسيليوس الكبير","letter":"B","status":"Saint · Bishop and Doctor","place":"Cappadocia","years":"c. 330–379","storyEn":"Basil was a bishop, theologian and organiser of charitable care. He encouraged communities to serve people in need and helped shape eastern Christian monastic life.","storyAr":"كان باسيليوس أسقفًا ولاهوتيًا ومنظّمًا لأعمال المحبّة. شجّع الجماعات على خدمة المحتاجين وأسهم في بناء الحياة الرهبانيّة المسيحيّة الشرقيّة."},{"en":"Gregory Nazianzen","ar":"القديس غريغوريوس النزينزي","letter":"G","status":"Saint · Bishop and Doctor","place":"Cappadocia","years":"c. 329–390","storyEn":"Gregory became known for his theological orations and his teaching about the Trinity. His work earned him a lasting place among the great teachers of the early Church.","storyAr":"اشتهر غريغوريوس بعظاته اللاهوتيّة وتعليمه حول الثالوث الأقدس. ومنحته كتاباته مكانة راسخة بين كبار معلّمي الكنيسة الأولى."},{"en":"John Chrysostom","ar":"القديس يوحنا الذهبيّ الفم","letter":"J","status":"Saint · Bishop and Doctor","place":"Antioch & Constantinople","years":"c. 347–407","storyEn":"John was a gifted preacher whose clear sermons called people to live the Gospel and care for the poor. His liturgical tradition remains especially important in eastern Christianity.","storyAr":"كان يوحنا واعظًا موهوبًا دعت عظاته الواضحة الناس إلى عيش الإنجيل والاهتمام بالفقراء. ولا يزال التقليد الليتورجيّ المرتبط به مهمًا في المسيحيّة الشرقيّة."},{"en":"Nicholas of Myra","ar":"القديس نيقولاوس","letter":"N","status":"Saint · Bishop","place":"Myra, Lycia","years":"4th century","storyEn":"Nicholas is remembered as a bishop known for generosity and care for people in need. Stories about his discreet acts of charity helped make him one of the most beloved saints across Christian traditions.","storyAr":"يُذكر نيقولاوس كأسقف عُرف بالسخاء والاهتمام بالمحتاجين. وأسهمت قصص عطائه الخفيّ في جعله من أكثر القديسين محبّة في التقاليد المسيحيّة."},{"en":"George","ar":"القديس جاورجيوس","letter":"G","status":"Saint · Martyr","place":"Early Christian tradition","years":"Traditionally 3rd–4th century","storyEn":"George is venerated as a Christian martyr whose courage became a symbol of steadfast faith. Many cultures tell stories about him, but the details of the dragon legend belong to later tradition.","storyAr":"يُكرَّم جاورجيوس كشَهيد مسيحيّ أصبحت شجاعته رمزًا للثبات في الإيمان. وتروي ثقافات كثيرة قصصًا عنه، أمّا حكاية التنّين فتعود إلى تقاليد لاحقة."},{"en":"Lucy of Syracuse","ar":"القديسة لوسيا","letter":"L","status":"Saint · Martyr","place":"Syracuse, Sicily","years":"Died c. 304","storyEn":"Lucy is remembered as an early Christian martyr from Syracuse. Her name became associated with light, and devotion to her spread widely through the Christian world.","storyAr":"تُذكر لوسيا كشهيدة مسيحيّة من سيراكوزا. ارتبط اسمها بالنور، وانتشر إكرامها على نطاق واسع في العالم المسيحيّ."},{"en":"Agnes of Rome","ar":"القديسة أغنيس","letter":"A","status":"Saint · Martyr","place":"Rome","years":"Died c. 304","storyEn":"Agnes is honoured as a young Roman martyr who remained faithful to her Christian convictions. Her witness became a lasting symbol of courage and fidelity.","storyAr":"تُكرَّم أغنيس كشابّة رومانيّة شهيدة تمسّكت بمعتقداتها المسيحيّة. وأصبحت شهادتها رمزًا دائمًا للشجاعة والأمانة."},{"en":"Cecilia","ar":"القديسة سيسيليا","letter":"C","status":"Saint · Martyr","place":"Rome","years":"Early Christian tradition","storyEn":"Cecilia is venerated as a Roman martyr and is traditionally regarded as the patron saint of music. Her story has inspired centuries of sacred art and music.","storyAr":"تُكرَّم سيسيليا كشهيدة رومانيّة، ويعتبرها التقليد شفيعة الموسيقى. وقد ألهمت قصّتها الفنّ والموسيقى المقدّسة عبر القرون."},{"en":"Patrick of Ireland","ar":"القديس باتريك","letter":"P","status":"Saint · Missionary","place":"Ireland","years":"5th century","storyEn":"Patrick was a missionary bishop who helped spread Christianity in Ireland. His writings and later traditions remember a life devoted to preaching, prayer and forming Christian communities.","storyAr":"كان باتريك أسقفًا مرسلًا ساهم في انتشار المسيحيّة في إيرلندا. وتذكر كتاباته والتقاليد اللاحقة حياة كرّسها للكرازة والصلاة وتأسيس الجماعات المسيحيّة."},{"en":"Francis Xavier","ar":"القديس فرنسيس كسفاريوس","letter":"F","status":"Saint · Missionary","place":"Navarre, Spain; Asia","years":"1506–1552","storyEn":"Francis Xavier was a Jesuit missionary who travelled through India, Southeast Asia and Japan. His letters describe his work sharing the Christian faith across cultures.","storyAr":"كان فرنسيس كسفاريوس مرسلًا يسوعيًا جاب الهند وجنوب شرق آسيا واليابان. وتصف رسائله عمله في مشاركة الإيمان المسيحيّ عبر ثقافات مختلفة."},{"en":"Ignatius of Loyola","ar":"القديس إغناطيوس دي لويولا","letter":"I","status":"Saint · Founder","place":"Basque Country, Spain","years":"c. 1491–1556","storyEn":"After a serious injury changed his life, Ignatius turned toward prayer and spiritual discernment. He founded the Society of Jesus, known as the Jesuits, and developed the Spiritual Exercises.","storyAr":"بعد إصابة خطيرة غيّرت حياته، اتّجه إغناطيوس إلى الصلاة والتمييز الروحيّ. أسّس جمعيّة يسوع، المعروفة باليسوعيّين، ووضع الرياضات الروحيّة."},{"en":"Teresa of Ávila","ar":"القديسة تريزا الأفيليّة","letter":"T","status":"Saint · Doctor of the Church","place":"Ávila, Spain","years":"1515–1582","storyEn":"Teresa was a Carmelite reformer and spiritual writer who taught about prayer and friendship with God. Her works remain important guides to the contemplative life.","storyAr":"كانت تريزا مصلحة كرملية وكاتبة روحيّة علّمت عن الصلاة والصداقة مع الله. ولا تزال مؤلّفاتها أدلّة مهمّة للحياة التأمّليّة."},{"en":"John of the Cross","ar":"القديس يوحنا الصليب","letter":"J","status":"Saint · Doctor of the Church","place":"Spain","years":"1542–1591","storyEn":"John was a Carmelite priest, poet and spiritual teacher. His writings describe the journey of faith, purification and union with God.","storyAr":"كان يوحنا كاهنًا كرملّيًا وشاعرًا ومعلّمًا روحيًا. تصف كتاباته مسيرة الإيمان والتطهير والاتّحاد بالله."},{"en":"Thérèse of Lisieux","ar":"القديسة تريزيا الطفل يسوع","letter":"T","status":"Saint · Doctor of the Church","place":"Lisieux, France","years":"1873–1897","storyEn":"Thérèse entered the Carmelite convent as a young woman and taught what she called the Little Way: trusting God through small acts of love. Her autobiography became widely read.","storyAr":"دخلت تريزيا دير الكرمل وهي شابّة، وعلّمت ما سمّته الطريق الصغيرة: الثقة بالله من خلال أعمال المحبّة البسيطة. وانتشرت سيرتها الذاتيّة على نطاق واسع."},{"en":"John Bosco","ar":"القديس يوحنا بوسكو","letter":"J","status":"Saint · Educator","place":"Turin, Italy","years":"1815–1888","storyEn":"Don Bosco devoted his life to educating and accompanying young people, especially those who were poor or vulnerable. He founded the Salesians and promoted education rooted in kindness and faith.","storyAr":"كرّس دون بوسكو حياته لتربية الشباب ومرافقتهم، ولا سيّما الفقراء والمعرّضين للخطر. أسّس الرهبنة السالسيّة وشجّع تربية تقوم على اللطف والإيمان."},{"en":"Vincent de Paul","ar":"القديس منصور دي بول","letter":"V","status":"Saint · Priest","place":"France","years":"1581–1660","storyEn":"Vincent organised practical service for people living in poverty and helped renew charitable ministry in the Church. His legacy inspired the Vincentian family and many works of service.","storyAr":"نظّم منصور خدمة عمليّة للفقراء وأسهم في تجديد العمل الخيريّ في الكنيسة. وألهم إرثه العائلة الفنسنتيّة وأعمال خدمة كثيرة."},{"en":"Martin de Porres","ar":"القديس مارتن دي بورّيس","letter":"M","status":"Saint · Dominican brother","place":"Lima, Peru","years":"1579–1639","storyEn":"Martin was a Dominican brother known for humility, care for the sick and service to people across social divisions. He is remembered as a witness to compassion and equality.","storyAr":"كان مارتن أخًا دومينيكانيًا عُرف بالتواضع والعناية بالمرضى وخدمة الناس من مختلف الطبقات. ويُذكر شاهدًا على الرحمة والمساواة."},{"en":"Rose of Lima","ar":"القديسة روزا دي ليما","letter":"R","status":"Saint · Lay Dominican","place":"Lima, Peru","years":"1586–1617","storyEn":"Rose lived a life of prayer and service, caring especially for people who were poor and ill. She became the first person from the Americas to be canonised.","storyAr":"عاشت روزا حياة صلاة وخدمة، واهتمّت خصوصًا بالفقراء والمرضى. وأصبحت أوّل شخص من الأميركتين يُعلن قديسًا."},{"en":"Kateri Tekakwitha","ar":"القديسة كاتيري تيكاكويثا","letter":"K","status":"Saint · Laywoman","place":"Mohawk territory / Canada","years":"1656–1680","storyEn":"Kateri was a Mohawk woman who became Christian and lived a life of prayer and service despite difficulties. She is honoured as the first Indigenous person from North America to be canonised.","storyAr":"كانت كاتيري امرأة من شعب الموهوك اعتنقت المسيحيّة وعاشت حياة صلاة وخدمة رغم الصعوبات. وتُكرَّم كأوّل شخص من سكّان أميركا الأصليّين في أميركا الشماليّة يُعلن قديسًا."},{"en":"Josephine Bakhita","ar":"القديسة جوزفين بخيتة","letter":"J","status":"Saint · Religious sister","place":"Sudan & Italy","years":"c. 1869–1947","storyEn":"Bakhita was born in Sudan and endured enslavement before finding freedom in Italy. She became a Canossian sister and is remembered for forgiveness, dignity and hope.","storyAr":"وُلدت بخيتة في السودان وعانت الاستعباد قبل أن تنال الحرّيّة في إيطاليا. أصبحت راهبة كانوسيّة وتُذكر للمغفرة والكرامة والرجاء."},{"en":"Maximilian Kolbe","ar":"القديس مكسيميليان كولبه","letter":"M","status":"Saint · Franciscan priest","place":"Poland","years":"1894–1941","storyEn":"Maximilian Kolbe was a Franciscan priest who founded a media apostolate and was imprisoned during the Second World War. He is remembered for an act of self-giving love at Auschwitz.","storyAr":"كان مكسيميليان كولبه كاهنًا فرنسيسكانيًا أسّس عملًا تبشيريًا إعلاميًا وسُجن خلال الحرب العالميّة الثانية. ويُذكر لموقفه الذي جسّد المحبّة وبذل الذات في أوشفيتز."},{"en":"Oscar Romero","ar":"القديس أوسكار روميرو","letter":"O","status":"Saint · Archbishop and martyr","place":"El Salvador","years":"1917–1980","storyEn":"Oscar Romero spoke publicly for the dignity of the poor and called for an end to violence in El Salvador. He was killed while celebrating Mass and canonised in 2018.","storyAr":"دافع أوسكار روميرو علنًا عن كرامة الفقراء ودعا إلى إنهاء العنف في السلفادور. قُتل أثناء احتفاله بالقدّاس وأُعلن قديسًا سنة 2018."},{"en":"Mother Teresa of Calcutta","ar":"القديسة الأم تريزا","letter":"M","status":"Saint · Founder","place":"Skopje; ministry in India","years":"1910–1997","storyEn":"Mother Teresa founded the Missionaries of Charity and served people who were poor and sick in Kolkata and beyond. Her work became known around the world; she was canonised in 2016.","storyAr":"أسّست الأم تريزا راهبات مرسلات المحبّة وخدمت الفقراء والمرضى في كولكاتا وخارجها. اشتهر عملها في العالم وأُعلنت قديسة سنة 2016."},{"en":"John Paul II","ar":"القديس البابا يوحنا بولس الثاني","letter":"J","status":"Saint · Pope","place":"Poland & Vatican","years":"1920–2005","storyEn":"John Paul II served as pope from 1978 to 2005 and travelled widely, encouraging dialogue, peace and the dignity of every person. He was canonised in 2014.","storyAr":"خدم يوحنا بولس الثاني بابا من 1978 إلى 2005، وسافر كثيرًا مشجّعًا الحوار والسلام وكرامة كل إنسان. أُعلن قديسًا سنة 2014."},{"en":"Paul VI","ar":"القديس البابا بولس السادس","letter":"P","status":"Saint · Pope","place":"Italy & Vatican","years":"1897–1978","storyEn":"Paul VI guided the Church through the closing years of the Second Vatican Council and its early implementation. He promoted dialogue with the modern world and was canonised in 2018.","storyAr":"قاد بولس السادس الكنيسة خلال السنوات الأخيرة من المجمع الفاتيكاني الثاني وبداية تطبيق قراراته. وشجّع الحوار مع العالم الحديث وأُعلن قديسًا سنة 2018."},{"en":"John XXIII","ar":"القديس البابا يوحنا الثالث والعشرون","letter":"J","status":"Saint · Pope","place":"Italy & Vatican","years":"1881–1963","storyEn":"John XXIII convoked the Second Vatican Council, seeking renewal and a more open dialogue between the Church and the world. He was canonised in 2014.","storyAr":"دعا يوحنا الثالث والعشرون إلى المجمع الفاتيكاني الثاني سعيًا إلى تجديد الكنيسة وحوار أوسع بينها وبين العالم. أُعلن قديسًا سنة 2014."},{"en":"Pier Giorgio Frassati","ar":"القديس بيير جورجيو فراسّاتي","letter":"P","status":"Saint · Layman","place":"Turin, Italy","years":"1901–1925","storyEn":"Pier Giorgio was a young Italian layman who loved the mountains, friendship and serving people in poverty. His faith shaped an active life of charity and public responsibility.","storyAr":"كان بيير جورجيو شابًا إيطاليًا أحبّ الجبال والصداقة وخدمة الفقراء. شكّل إيمانه حياة عمليّة من المحبّة والمسؤوليّة الاجتماعيّة."},{"en":"Carlo Acutis","ar":"القديس كارلو أكوتيس","letter":"C","status":"Saint · Layman","place":"London & Italy","years":"1991–2006","storyEn":"Carlo was a young Catholic who used his computer skills to document Eucharistic miracles and share his faith online. He is remembered for combining ordinary teenage life with prayer and service.","storyAr":"كان كارلو شابًا كاثوليكيًا استخدم مهاراته الرقميّة لتوثيق المعجزات الإفخارستيّة ومشاركة إيمانه عبر الإنترنت. ويُذكر لجمعه بين الحياة اليوميّة والصلاة والخدمة."},{"en":"Elizabeth of Hungary","ar":"القديسة إليصابات المجريّة","letter":"E","status":"Saint · Princess and charitable worker","place":"Hungary & Germany","years":"1207–1231","storyEn":"Elizabeth used her position and resources to care for people who were poor and sick. After her husband's death she devoted herself more fully to charitable service.","storyAr":"استخدمت إليصابات مكانتها ومواردها للعناية بالفقراء والمرضى. وبعد وفاة زوجها كرّست نفسها بصورة أكبر لأعمال المحبّة والخدمة."},{"en":"Catherine of Siena","ar":"القديسة كاترينا السيانيّة","letter":"C","status":"Saint · Doctor of the Church","place":"Siena, Italy","years":"1347–1380","storyEn":"Catherine was a Dominican laywoman, mystic and writer who urged Church leaders toward reform and reconciliation. Her letters and spiritual writings remain influential.","storyAr":"كانت كاترينا علمانيّة دومينيكانيّة ومتأمّلة وكاتبة دعت قادة الكنيسة إلى الإصلاح والمصالحة. ولا تزال رسائلها وكتاباتها الروحيّة مؤثّرة."}]);
  entries.forEach((entry, index) => { entry.group = index < 12 ? "Lebanese" : (index < 28 ? "Lebanese" : "Worldwide"); });
  entries.push(...[{"en":"John Maron","ar":"القديس يوحنا مارون","letter":"J","status":"Saint · First Maronite patriarch","place":"Kfarhay · كفرحي، شمال لبنان","years":"Died traditionally c. 707","storyEn":"John Maron is venerated as the first Maronite patriarch and one of the central figures in the formation of the Maronite Church. Church tradition connects his ministry with the communities of Mount Lebanon and the northern coastal region. He is remembered not simply as a church leader, but as a shepherd who helped a community preserve its worship, identity and communion through a period of political and theological conflict. Accounts of his life were written many generations later, and dates and details differ between sources; this biography therefore distinguishes the strong place of his memory in Maronite tradition from details that cannot be firmly reconstructed.","storyAr":"يُكرَّم يوحنا مارون بوصفه أوّل بطريرك ماروني، ومن الشخصيّات الأساسيّة في نشأة الكنيسة المارونيّة. ويربط التقليد الكنسي خدمته بجماعات جبل لبنان والمنطقة الساحليّة الشماليّة. ولا يُذكر فقط كقائد كنسي، بل كراعٍ ساعد جماعته على صون عبادتها وهويّتها وشركتها الكنسيّة وسط صراعات سياسيّة ولاهوتيّة. كُتبت أخبار حياته بعد أجيال من زمنه، وتختلف المصادر في بعض التواريخ والتفاصيل؛ لذلك تميّز هذه السيرة بين مكانته الراسخة في الذاكرة المارونيّة وبين التفاصيل التي يصعب إثباتها تاريخيًّا."},{"en":"Theodosia of Tyre","ar":"القديسة ثيودوسيا من صور","letter":"T","status":"Saint · Martyr in ancient tradition","place":"Tyre · صور","years":"Early 4th century · traditionally c. 307","storyEn":"Theodosia is remembered in Christian martyrology as a young Christian woman of Tyre during the Great Persecution. The traditional account says that she approached imprisoned Christians to encourage them and was herself arrested. Her story became a witness to the courage of ordinary believers who supported one another when public profession of Christianity could bring danger. The surviving accounts belong to the ancient hagiographical tradition and should be read with the care normally given to early martyr narratives; the historical record does not provide a modern biography or independently verifiable details for every episode.","storyAr":"تُذكر ثيودوسيا في السنكسارات المسيحيّة كشابّة مسيحيّة من صور عاشت في زمن الاضطهاد الكبير. وتروي السيرة التقليديّة أنّها اقتربت من مسيحيّين مسجونين لتشجّعهم، فاعتُقلت هي أيضًا. وأصبحت قصّتها شهادة على شجاعة المؤمنين العاديّين الذين ساند بعضهم بعضًا حين كان إعلان الإيمان بالمسيحيّة يعرّضهم للخطر. تنتمي الأخبار المتبقيّة إلى تقليد سير الشهداء القديم، وينبغي قراءتها مع التنبّه إلى أنّ المصادر لا تقدّم سيرة حديثة موثّقة لكلّ تفاصيل الرواية."},{"en":"Eudocia of Heliopolis","ar":"القديسة أفدوكيا من هليوبوليس","letter":"E","status":"Saint · Martyr in ancient tradition","place":"Heliopolis · بعلبك","years":"Ancient tradition · 2nd century","storyEn":"Eudocia is associated in Eastern Christian tradition with Heliopolis, the ancient city at the site of modern Baalbek. Her traditional story describes a woman who turned away from her former life after hearing Christian teaching and reading the Scriptures, then devoted herself to prayer and charity. Later accounts describe her as suffering martyrdom. The details and chronology vary across hagiographical sources, so the website presents her as a figure of local Christian memory rather than claiming that every episode is historically established.","storyAr":"يرتبط اسم أفدوكيا في التقليد المسيحي الشرقي بهليوبوليس، المدينة القديمة التي تقوم في موقع بعلبك اليوم. وتروي سيرتها التقليديّة أنّها ابتعدت عن حياتها السابقة بعدما سمعت التعليم المسيحي وقرأت الكتب المقدّسة، ثم كرّست نفسها للصلاة وأعمال الرحمة. وتذكر روايات لاحقة أنّها نالت إكليل الشهادة. تختلف التفاصيل والتواريخ بين مصادر سير القديسين، لذلك تعرضها هذه الصفحة كشخصيّة من الذاكرة المسيحيّة المحليّة، من دون اعتبار كلّ أحداث الرواية مثبتة تاريخيًّا."},{"en":"Pamphilus of Beirut","ar":"القديس بامفيلس من بيروت","letter":"P","status":"Saint · Priest and martyr","place":"Beirut · بيروت; ministry in Caesarea","years":"Died 309","storyEn":"Pamphilus was a Christian priest and scholar remembered for his work in Caesarea Maritima, where he helped build an important Christian library and supported the careful copying and study of Scripture. Ancient sources associate his origins with Beirut. During the persecution under Emperor Diocletian, he was imprisoned and later executed. His legacy is especially important for the history of biblical scholarship: he represents the early Church’s effort to preserve, study and transmit Christian texts as well as its witness under persecution. Some biographical details come from ancient ecclesiastical histories.","storyAr":"كان بامفيلس كاهنًا وعالمًا مسيحيًّا يُذكر بعمله في قيصريّة البحريّة، حيث ساهم في إنشاء مكتبة مسيحيّة مهمّة وفي نسخ الكتاب المقدّس ودراسته بعناية. وتربط مصادر قديمة أصوله بمدينة بيروت. خلال اضطهاد الإمبراطور دقلديانوس، سُجن ثم أُعدم. وتكمن أهميّة إرثه خصوصًا في تاريخ الدراسات الكتابيّة؛ فهو يمثّل سعي الكنيسة الأولى إلى حفظ النصوص المسيحيّة ودراستها ونقلها، إلى جانب شهادتها للإيمان في زمن الاضطهاد. وتستند بعض تفاصيل سيرته إلى تواريخ كنسيّة قديمة."},{"en":"Christina of Tyre","ar":"القديسة كريستينا من صور","letter":"C","status":"Saint · Martyr in ancient tradition","place":"Tyre · صور","years":"Ancient tradition · 4th century","storyEn":"Christina of Tyre appears in some local and later Christian accounts as a young woman who rejected the worship of idols and chose the Christian faith. The stories describe conflict with her family and authorities, followed by martyrdom. Her account is sometimes confused with other saints named Christina, especially Christina of Bolsena; the historical traditions are not always consistent. This profile keeps the Tyrian association visible while noting that the details belong to hagiographical tradition and require careful source distinction.","storyAr":"تظهر كريستينا من صور في بعض الروايات المسيحيّة المحليّة والمتأخّرة كشابّة رفضت عبادة الأصنام واختارت الإيمان المسيحي. وتروي القصص خلافًا بينها وبين عائلتها والسلطات، ثم استشهادها. وقد تختلط سيرتها أحيانًا بسِيَر قديسات أخريات يحملن اسم كريستينا، ولا سيّما كريستينا من بولسينا، كما أنّ الروايات التاريخيّة ليست متّفقة في كلّ تفاصيلها. تُبقي هذه البطاقة ارتباطها بصور واضحًا، مع التنبيه إلى أنّ التفاصيل تنتمي إلى تقليد سير القديسين وتحتاج إلى تمييز دقيق بين المصادر."},{"en":"Leontios of Tripoli","ar":"القديس ليونتيوس الطرابلسي","letter":"L","status":"Saint · Martyr with companions in tradition","place":"Tripoli · طرابلس، فينيقيا","years":"Ancient tradition · 1st century","storyEn":"Leontios is honoured in an ancient Christian tradition connected with Tripoli in Phoenicia. The account tells of a Roman officer who encountered Christian teaching, embraced the faith and was put to death with companions remembered as Hypatios and Theodoulos. The names and setting are preserved in martyrological traditions, but the chronology and narrative details are not equally supported by surviving historical evidence. His entry is included to represent the early Christian memory of the northern Lebanese coast, with the uncertainty made explicit.","storyAr":"يُكرَّم ليونتيوس في تقليد مسيحي قديم مرتبط بطرابلس الفينيقيّة. وتروي الرواية أنّ ضابطًا رومانيًّا تعرّف إلى التعليم المسيحي واعتنق الإيمان، ثم قُتل مع رفيقَيه اللذين يُذكران باسمَي هيباتيوس وثيودولوس. حُفظت الأسماء والمكان في تقاليد السنكسارات، لكنّ التسلسل الزمني وتفاصيل الرواية لا تستند كلّها إلى أدلّة تاريخيّة متساوية القوّة. أُدرجت سيرته لإظهار الذاكرة المسيحيّة القديمة للساحل اللبناني الشمالي، مع توضيح حدود المعلومات المتاحة."},{"en":"Hypatios of Tripoli","ar":"القديس هيباتيوس الطرابلسي","letter":"H","status":"Saint · Martyr with companions in tradition","place":"Tripoli · طرابلس، فينيقيا","years":"Ancient tradition · 1st century","storyEn":"Hypatios is named in the traditional account of the Christian martyrs associated with Leontios of Tripoli and Theodoulos. The story places their witness in Roman-era Phoenicia and remembers them as companions who shared the same commitment to Christ. Very little independent biographical information survives about Hypatios, and the account is preserved chiefly through later martyrological tradition. The website therefore records his commemoration without presenting uncertain narrative details as established fact.","storyAr":"يَرِد اسم هيباتيوس في الرواية التقليديّة لشهداء طرابلس المرتبطين بليونتيوس وثيودولوس. وتضع الرواية شهادتهم في فينيقيا في العصر الروماني، وتذكرهم رفقاء تشاركوا الثبات في الإيمان بالمسيح. لا تتوافر معلومات سيريّة مستقلّة كثيرة عن هيباتيوس، إذ حُفظت قصّته أساسًا في تقاليد السنكسارات اللاحقة. لذلك تسجّل الصفحة تذكاره من دون عرض التفاصيل غير المؤكّدة كأنّها حقائق ثابتة."},{"en":"Theodoulos of Tripoli","ar":"القديس ثيودولوس الطرابلسي","letter":"T","status":"Saint · Martyr with companions in tradition","place":"Tripoli · طرابلس، فينيقيا","years":"Ancient tradition · 1st century","storyEn":"Theodoulos is remembered alongside Leontios and Hypatios in a traditional account of early Christian witness at Tripoli. Later calendars preserve the names of the three companions, although the surviving historical record is limited and the details of the story vary. His commemoration points to the ancient Christian communities of the Phoenician coast and to the way local churches preserved the memory of believers who were understood to have suffered for their faith.","storyAr":"يُذكر ثيودولوس إلى جانب ليونتيوس وهيباتيوس في رواية تقليديّة عن الشهادة المسيحيّة الأولى في طرابلس. وقد حفظت التقاويم الكنسيّة اللاحقة أسماء الرفقاء الثلاثة، مع أنّ السجلّ التاريخي المتبقي محدود وتختلف تفاصيل القصّة بين الروايات. ويشير تذكاره إلى الجماعات المسيحيّة القديمة على الساحل الفينيقي وإلى الطريقة التي حفظت بها الكنائس المحليّة ذكرى المؤمنين الذين اعتُبروا شهداء من أجل إيمانهم."},{"en":"The 500 Martyrs of Tyre","ar":"الخمسمئة شهيد من صور","letter":"F","status":"Martyrs · Collective commemoration in tradition","place":"Tyre · صور","years":"Traditionally commemorated in 304","storyEn":"A collective Christian commemoration remembers a large group of believers from Tyre who suffered during the persecutions associated with Emperor Diocletian. Later accounts give the number as five hundred and describe the group’s death as a public act of imperial persecution. Because the surviving sources are brief and the number belongs to the traditional account, this entry treats the figure as a liturgical and historical memory rather than a verified census. Their commemoration recalls the cost borne by early Christian communities along the Phoenician coast.","storyAr":"يحفظ التقليد الكنسي تذكار جماعة كبيرة من المؤمنين في صور الذين عانوا خلال الاضطهادات المرتبطة بالإمبراطور دقلديانوس. وتذكر روايات لاحقة أنّ عددهم بلغ خمسمئة، وتصف موتهم في سياق اضطهاد علني من السلطة الرومانيّة. وبما أنّ المصادر المتبقيّة موجزة وأنّ العدد جزء من الرواية التقليديّة، تعرض الصفحة الرقم كتذكار ليتورجي وذاكرة تاريخيّة لا كإحصاء مثبت. ويذكّرنا تذكارهم بما تحمّلته الجماعات المسيحيّة الأولى على الساحل الفينيقي."},{"en":"The 350 Disciples of Saint Maron","ar":"الثلاثمئة والخمسون من تلاميذ القديس مارون","letter":"T","status":"Martyrs · Maronite historical tradition","place":"Mount Lebanon and the region · جبل لبنان والمشرق","years":"Traditionally commemorated in 517","storyEn":"Maronite historical memory preserves the account of disciples associated with Saint Maron who were killed during conflicts in the early sixth century. Later tradition gives their number as three hundred and fifty and remembers them as witnesses who remained faithful to their Church. The political and theological conflicts of that period were complex, and modern historians discuss the sources and circumstances carefully. This profile honours the community’s liturgical memory while making clear that the precise number and every detail of the traditional account are not independently certain.","storyAr":"تحفظ الذاكرة التاريخيّة المارونيّة رواية تلاميذ ارتبطوا بالقديس مارون وقُتلوا خلال صراعات مطلع القرن السادس. وتذكر التقاليد اللاحقة أنّ عددهم بلغ ثلاثمئة وخمسين، وتكرّمهم كشهود ثبتوا في أمانتهم لكنيستهم. كانت الصراعات السياسيّة واللاهوتيّة في تلك المرحلة معقّدة، ويناقش المؤرّخون المعاصرون مصادرها وظروفها بحذر. تكرّم هذه البطاقة الذاكرة الليتورجيّة للجماعة، مع توضيح أنّ العدد الدقيق وجميع تفاصيل الرواية التقليديّة ليست مؤكّدة بأدلّة مستقلّة."},{"en":"Marina the Monk","ar":"القديسة مارينا المتوحّدة","letter":"M","status":"Saint · Venerated in Eastern tradition","place":"Lebanese monastic tradition · تقليد رهباني لبناني","years":"Traditionally 5th century","storyEn":"Marina is venerated in Eastern Christian tradition through a story of devotion, humility and silence. The traditional account says she entered a monastery disguised as a man so that she could remain close to her father, who had also embraced monastic life. When she was falsely accused of fathering a child, she accepted blame without revealing her identity, and only after her death was the truth discovered. The story has circulated in several forms and is not a modern documentary biography; in Lebanon she is especially associated with monastic memory and devotion.","storyAr":"تُكرَّم مارينا في التقليد المسيحي الشرقي من خلال سيرة تتحدّث عن التفاني والتواضع والصمت. وتقول الرواية التقليديّة إنّها دخلت ديرًا متنكرة بهيئة رجل لتبقى قريبة من والدها الذي اختار الحياة الرهبانيّة أيضًا. وعندما اتُّهمت ظلمًا بأنّها أمّ طفل، قبلت الاتّهام من دون كشف هويّتها، ولم تظهر الحقيقة إلّا بعد وفاتها. انتشرت القصّة بصيغ متعدّدة، وليست سيرة توثيقيّة حديثة؛ وترتبط في لبنان بالذاكرة الرهبانيّة والإكرام الشعبي."},{"en":"Joseph of Damascus","ar":"القديس يوسف الدمشقي","letter":"J","status":"Orthodox saint · Priest and martyr","place":"Born in Beirut · بيروت; martyred in Damascus","years":"Martyred 1860","storyEn":"Joseph of Damascus was an Antiochian Orthodox priest and teacher born in Beirut. He served the Christian community in Damascus during a period of intense tension and violence in 1860. Church tradition remembers him among those killed during the Damascus persecution, on the same day associated with the Massabki brothers. His story belongs to the wider shared Christian heritage of Lebanon and Syria and is included here with his Orthodox identity clearly stated, rather than implying that he belongs to the Catholic canonisation process.","storyAr":"كان يوسف الدمشقي كاهنًا ومعلّمًا من كنيسة أنطاكية الأرثوذكسيّة، وُلد في بيروت وخدم الجماعة المسيحيّة في دمشق خلال مرحلة توتّر وعنف شديدين سنة 1860. وتكرّمه الذاكرة الكنسيّة بين الذين قُتلوا في اضطهاد دمشق، في اليوم نفسه المرتبط باستشهاد الإخوة المسابكي. تنتمي سيرته إلى التراث المسيحي المشترك بين لبنان وسوريا، لذلك أُدرج هنا مع توضيح انتمائه الأرثوذكسي، لا باعتباره جزءًا من مسار إعلان القداسة الكاثوليكي."},{"en":"Blessed Jacques Haddad (Abouna Yaacoub)","ar":"الطوباوي الأب يعقوب الحداد الكبوشي","letter":"J","status":"Blessed · Capuchin priest","place":"Ghazir · غزير","years":"1875–1954","storyEn":"Khalil Haddad, known in religious life as Father Jacques, was born in Ghazir in 1875 and became a Capuchin priest. He devoted himself to preaching, education and practical care for people who were poor, sick or abandoned. He founded the Congregation of the Franciscan Sisters of the Cross and established works of care that developed into hospitals and social services. His ministry combined public preaching with direct service: he sought out people in need and organised lasting institutions to support them. He was beatified in 2008, and is widely known in Lebanon as Abouna Yaacoub.","storyAr":"وُلد خليل الحداد، المعروف في الحياة الرهبانيّة باسم الأب يعقوب، في غزير سنة 1875، وأصبح كاهنًا كبوشيًا. كرّس حياته للكرازة والتربية والعناية العمليّة بالفقراء والمرضى والمتروكين. أسّس جمعيّة راهبات الصليب الفرنسيسكانيّات، وأقام مؤسّسات للرعاية تطوّرت إلى مستشفيات وخدمات اجتماعيّة. جمعت خدمته بين الوعظ والعمل المباشر؛ فكان يبحث عن المحتاجين وينظّم مؤسّسات دائمة لمساندتهم. أُعلن طوباويًا سنة 2008، ويُعرف في لبنان باسم الأب يعقوب."},{"en":"Elias Hoayek","ar":"الطوباوي البطريرك الياس الحويّك","letter":"E","status":"Blessed · Maronite patriarch · beatified 2026","place":"Helta · حلتا، البترون","years":"1843–1931 · Beatified 2026","storyEn":"Elias Hoayek was born in Helta in the Batroun district in 1843 and became the 72nd Maronite Patriarch. His long patriarchate included a period of famine, war and the political upheavals surrounding the emergence of modern Lebanon. He is remembered for pastoral care during hardship, for founding the Congregation of the Maronite Sisters of the Holy Family, and for his role in advocating for the establishment of Greater Lebanon in 1920. Pope Leo XIV authorised the decree recognising a miracle attributed to his intercession in May 2026; he was beatified in Dimane on 25 July 2026. He is therefore correctly listed as Blessed, not merely Venerable.","storyAr":"وُلد الياس الحويّك في حلتا، قضاء البترون، سنة 1843، وأصبح البطريرك الماروني الثاني والسبعين. امتدّت بطريركيّته الطويلة خلال المجاعة والحرب والتحوّلات السياسيّة التي رافقت نشوء لبنان الحديث. يُذكر برعايته لأبناء الكنيسة في زمن الشدائد، وبإنشائه جمعيّة راهبات العائلة المقدّسة المارونيّات، وبدوره في المطالبة بقيام دولة لبنان الكبير سنة 1920. أذن البابا لاون الرابع عشر في أيار 2026 بإصدار مرسوم الاعتراف بأعجوبة منسوبة إلى شفاعته، وأُعلن طوباويًا في الديمان في 25 تموز 2026. لذلك يُدرج هنا بصفة طوباوي، لا مكرّم فقط."},{"en":"Antonios Tarabay","ar":"الأب أنطونيوس طربيه","letter":"A","imageUrl":"https://ouadiqadisha.com/wp-content/uploads/2022/01/20220114_171418.jpg?w=627","imagePage":"https://ouadiqadisha.com/mar-lichaa/","status":"Servant of God · Maronite hermit priest","place":"Ain el-Raha, Tannourine & Qannoubine Valley · عين الراحة، تنورين ووادي قاديشا","years":"1911–1998","storyEn":"Gabriel Youssef Tarabay was born in 1911 in Ain el-Raha, Tannourine, into a devout Maronite family. After the death of his parents, his uncle helped care for his upbringing. On 12 November 1928, at the age of seventeen, he entered the Mariamite Maronite Order at Our Lady of Louaize and began his novitiate under the religious name Iklimos. He continued his formation at monasteries including Mar Lichaa and Achkout, made his religious profession in 1930, and later took the name Antonios. He studied philosophy and theology and was ordained a priest in 1935. He served in several ministries and, at his own request, embraced the eremitical life in 1944. After a period at Beit Chebab and service as spiritual counsellor to the sisters of Hrash, he was sent in 1949 to the ancient Monastery of Saint Elisha (Mar Lichaa) in the Qadisha Valley. There he lived as a hermit for more than three decades, restoring the monastery and welcoming pilgrims and visitors who sought prayer, counsel and spiritual guidance. When his health deteriorated in 1981, he was transferred to the Christ the King infirmary; during the war he also spent time at the monastery of Saints Sarkis and Bacchus in Achkout before returning to Christ the King. He died on 20 June 1998 and was buried in a grotto beside the old monastery where he had lived as a hermit. His grave remains a place of prayer and pilgrimage. He is remembered with deep devotion in Lebanon and is referred to as a Servant of God in connection with his cause; he must not be described as beatified or canonised.","storyAr":"وُلد جبرائيل يوسف طربيه سنة 1911 في عين الراحة في تنورين، في عائلة مارونية مؤمنة. وبعد وفاة والديه، تولّى عمّه رعايته وتربيته. في 12 تشرين الثاني 1928، وكان في السابعة عشرة، دخل الرهبانية المريمية المارونية في دير سيّدة اللويزة وبدأ الابتداء باسم الأخ إقليموس. تابع تكوينه في أديرة منها مار أليشع وعشقوت، وأبرز نذوره الرهبانية سنة 1930، ثم اتخذ اسم أنطونيوس. درس الفلسفة واللاهوت ورُسم كاهنًا سنة 1935. خدم في رسالات مختلفة، ثم اختار الحياة النسكية سنة 1944. وبعد إقامته في بيت شباب وخدمته مرشدًا روحيًا لراهبات حراش، انتقل سنة 1949 إلى دير مار أليشع القديم في وادي قاديشا. عاش هناك ناسكًا لأكثر من ثلاثة عقود، وساهم في ترميم الدير واستقبل الحجّاج والزائرين الذين كانوا يقصدونه للصلاة وطلب المشورة والإرشاد الروحي. وعندما تدهورت صحته سنة 1981، نُقل إلى مستشفى دير المسيح الملك، وأقام خلال الحرب فترة في دير مار سركيس وباخوس في عشقوت، قبل أن يعود إلى مستشفى المسيح الملك. رقد في 20 حزيران 1998 ودُفن في مغارة قرب الدير القديم الذي عاش فيه ناسكًا. ولا يزال ضريحه مقصدًا للصلاة والحج. يُكرَّم بإكرام واسع في لبنان، ويُشار إليه بصفة خادم الله في سياق دعوى التطويب؛ ولا يجوز وصفه بالطوباوي أو القديس المعلن قانونيًا."},{"en":"Béchara Abou Mrad","ar":"الأب بشارة أبو مراد","letter":"B","status":"Servant of God · Cause for beatification","place":"Dahr el-Ahmar · دير الأحمر، البقاع","years":"1853–1930","storyEn":"Béchara Abou Mrad was a Melkite Greek Catholic priest associated with Dahr el-Ahmar in the Bekaa. He served parish communities through pastoral care, prayer and a reputation for personal holiness. Devotion to his memory continued after his death, and his cause has been presented in the Church’s process for beatification. The title Servant of God indicates that a cause has been opened; it does not mean that he has been beatified or canonised. His inclusion broadens the directory beyond the Maronite tradition to reflect Lebanon’s wider Eastern Catholic heritage.","storyAr":"كان بشارة أبو مراد كاهنًا من كنيسة الروم الملكيّين الكاثوليك، ارتبط اسمه بدير الأحمر في البقاع. خدم الرعايا من خلال الرعاية الكهنوتيّة والصلاة والسمعة المرتبطة بقداسة حياته. واستمرّ إكرام ذكراه بعد وفاته، وقد قُدّمت قضيّته ضمن مسار الكنيسة للتطويب. وتشير صفة خادم الله إلى افتتاح دعوى القداسة، ولا تعني أنّه أُعلن طوباويًا أو قديسًا. وتوسّع إضافته الدليل ليتجاوز التقليد الماروني ويعكس التراث الكاثوليكي الشرقي الأوسع في لبنان."}].map(entry => ({ ...entry, group: "Lebanese" })));

  // Remove duplicate names while keeping the newest, fuller biography.
  const seenSaintNames = new Set();
  for (let i = entries.length - 1; i >= 0; i--) {
    const key = entries[i].en.trim().toLocaleLowerCase();
    if (seenSaintNames.has(key)) entries.splice(i, 1);
    else seenSaintNames.add(key);
  }
  // Yaqub Haddad and Jacques Haddad are the same Lebanese Capuchin priest.
  for (let i = entries.length - 1; i >= 0; i--) {
    if (entries[i].en === "Yaqub Haddad") entries.splice(i, 1);
  }
  entries.push(...[{"en":"Francis Massabki","ar":"القديس فرنسيس المسابكي","letter":"F","status":"Canonized saint · Martyr · 2024","place":"Damascus; family roots in Lebanon · دمشق","years":"Martyred 1860","group":"Lebanese","storyEn":"Francis Massabki was a Maronite layman, husband and father, and one of three brothers remembered for their witness during the Damascus persecution of July 1860. Their family belonged to the Lebanese Maronite community living in Damascus. When pressured to abandon their Christian faith, the brothers remained steadfast. Their martyrdom became a lasting sign of courage and fidelity for Maronite Christians in Lebanon and the diaspora. Pope Francis canonized Francis, Abdel Moati and Raphael together on 20 October 2024. Their feast is celebrated on 10 July.","storyAr":"كان فرنسيس المسابكي علمانيًا مارونيًا وزوجًا وأبًا، وأحد الإخوة الثلاثة الذين تُكرّمهم الكنيسة لشهادتهم خلال اضطهاد دمشق في تموز 1860. تنتمي عائلتهم إلى الجماعة المارونيّة اللبنانيّة التي عاشت في دمشق. وعندما طُلب منهم التخلّي عن إيمانهم المسيحي، ثبتوا عليه. أصبحت شهادتهم علامة باقية على الشجاعة والأمانة لدى الموارنة في لبنان والاغتراب. أعلن البابا فرنسيس فرنسيس وعبد المعطي ورفائيل قديسين معًا في 20 تشرين الأول 2024. ويُحتفل بتذكارهم في 10 تموز."},{"en":"Abdel Moati Massabki","ar":"القديس عبد المعطي المسابكي","letter":"A","status":"Canonized saint · Martyr · 2024","place":"Damascus; family roots in Lebanon · دمشق","years":"Martyred 1860","group":"Lebanese","storyEn":"Abdel Moati Massabki was a Maronite layman from a respected Christian family in Damascus. He is remembered with his brothers Francis and Raphael for refusing to renounce their faith during the violence against Christians in July 1860. The brothers were not clergy or public officials; their witness came from the faith they lived as ordinary members of the Church and as part of a family. Their story has been handed down as an example of steadfastness under pressure. They were canonized together by Pope Francis on 20 October 2024.","storyAr":"كان عبد المعطي المسابكي علمانيًا مارونيًا من عائلة مسيحيّة معروفة عاشت في دمشق. وتُكرّمه الكنيسة مع أخويه فرنسيس ورفائيل لرفضهم التخلّي عن إيمانهم خلال الاعتداءات على المسيحيين في تموز 1860. لم يكن الإخوة رجال دين أو مسؤولين، بل جاءت شهادتهم من الإيمان الذي عاشوه كأعضاء عاديين في الكنيسة وكأفراد في عائلة. تناقلت الأجيال قصّتهم مثالًا على الثبات في الشدائد. أعلنهم البابا فرنسيس قديسين معًا في 20 تشرين الأول 2024."},{"en":"Raphael Massabki","ar":"القديس رفائيل المسابكي","letter":"R","status":"Canonized saint · Martyr · 2024","place":"Damascus; family roots in Lebanon · دمشق","years":"Martyred 1860","group":"Lebanese","storyEn":"Raphael Massabki was the third of the Maronite brothers Francis, Abdel Moati and Raphael, whose names are linked with the Damascus martyrs of 1860. The brothers were lay Christians and are remembered for remaining faithful when asked to abandon Christianity. Their commemoration reminds the Church that holiness is not limited to monasteries or ordained ministry: lay people and families can also bear courageous witness. Pope Francis canonized the three brothers together on 20 October 2024, recognizing their witness as saints of the universal Church.","storyAr":"كان رفائيل المسابكي الأخ الثالث مع فرنسيس وعبد المعطي، وترتبط أسماؤهم بشهداء دمشق سنة 1860. كان الإخوة من أبناء الجماعة المسيحيّة العلمانيّة، وتكرّمهم الكنيسة لثباتهم في الإيمان عندما طُلب منهم التخلّي عن المسيحيّة. ويذكّر تذكارهم بأنّ القداسة لا تقتصر على الأديرة أو الخدمة الكهنوتيّة؛ فالعلمانيّون والعائلات أيضًا يستطيعون تقديم شهادة شجاعة. أعلن البابا فرنسيس الإخوة الثلاثة قديسين معًا في 20 تشرين الأول 2024."}]);
  const expandedStories = {
    "Charbel Makhlouf": ["Before entering the monastery, Youssef grew up in a farming family and was influenced by the example of his maternal uncles, who lived as hermits. In the monastery he combined study and manual work with a disciplined rhythm of prayer. His years at Annaya were marked by simplicity and a desire to withdraw from public attention. After his death, reports of answers to prayer and healings drew pilgrims from many backgrounds.", "قبل دخوله الدير، نشأ يوسف في عائلة زراعيّة وتأثّر بمثال خاليه اللذين عاشا حياة النسك. جمع في الدير بين الدراسة والعمل اليدوي ونظام ثابت من الصلاة. وتميّزت سنواته في عنّايا بالبساطة والرغبة في الابتعاد عن الأضواء. وبعد وفاته، جذبت أخبار الاستجابات للصلوات والشفاءات حجّاجًا من خلفيّات متنوّعة."],
    "Nimatullah Al-Hardini": ["In religious life he served in several monasteries, taught young monks and worked in bookbinding and the preparation of liturgical books. His brotherhood remembered him for patience, humility and steady devotion to the Eucharist. One of his students was the young Youssef Makhlouf, later known as Saint Charbel, linking two generations of Lebanese Maronite monastic life.", "خلال حياته الرهبانيّة خدم في أديرة عدّة، وعلّم الرهبان الشبان، وعمل في تجليد الكتب وإعداد الكتب الليتورجيّة. وذكره إخوته الرهبان بصبره وتواضعه وتعبّده الثابت للقربان المقدّس. وكان من تلاميذه يوسف مخلوف الشاب، الذي عُرف لاحقًا بالقديس شربل، فجمع بينهما رابط روحي عبر جيلين من الرهبنة المارونيّة اللبنانيّة."],
    "Rafqa Pietra Choboq Ar-Rayès": ["Before becoming a nun, Rafqa experienced family loss and discerned her vocation through prayer and service. Her early religious work included teaching catechism and helping educate girls. She later joined the Lebanese Maronite Order and lived at the monastery of Saint Joseph in Jrabta. Her Vatican biography highlights her quiet service, prayer and perseverance; her feast is celebrated on 23 March.", "قبل أن تصبح راهبة، اختبرت رفقا فقدانًا عائليًا وميّزت دعوتها من خلال الصلاة والخدمة. شملت أعمالها الرهبانيّة الأولى تعليم التعليم المسيحي والمساعدة في تثقيف الفتيات. ثم انضمّت إلى الرهبنة اللبنانيّة المارونيّة وعاشت في دير مار يوسف في جربتا. وتُبرز سيرتها في الفاتيكان خدمتها الهادئة وصلاتها وثباتها؛ ويُحتفل بتذكارها في 23 آذار."],
    "Estephan El Douaihy": ["As a child he showed exceptional ability and was sent to the Maronite College in Rome, where he studied theology, languages and the intellectual traditions of the Church. After returning to the East he served as a priest and bishop before being elected patriarch in 1670. He wrote extensively on Maronite history, liturgy, music and theology, preserving material that might otherwise have been lost. His patriarchate involved hardship and repeated displacement, yet he continued visiting communities and strengthening church life. He was beatified in Bkerké on 2 August 2024.", "أظهر منذ طفولته قدرة علميّة لافتة، فأُرسل إلى المدرسة المارونيّة في روما حيث درس اللاهوت واللغات وتراث الكنيسة الفكري. وبعد عودته إلى الشرق خدم كاهنًا وأسقفًا قبل انتخابه بطريركًا سنة 1670. كتب بإسهاب عن التاريخ الماروني والليتورجيا والموسيقى واللاهوت، فحفظ مواد كان يمكن أن تضيع. وشهدت بطريركيّته مشقّات وتنقّلات متكرّرة، لكنه واصل زيارة الجماعات وتقوية الحياة الكنسيّة. أُعلن طوباويًا في بكركي في 2 آب 2024."],
    "Estephan Nehme": ["He spent his religious life in several monasteries of the Lebanese Maronite Order, carrying out ordinary duties with care and consistency. He was known for a spirituality centred on prayer, work and humility rather than public recognition. Those who knew him remembered his attentiveness to his brothers and his trust in God's presence in daily tasks. He died at the Monastery of Saints Cyprian and Justina in Kfifan and was beatified in 2010.", "قضى حياته الرهبانيّة في أديرة عدّة للرهبنة اللبنانيّة المارونيّة، حيث أدّى الأعمال اليوميّة بعناية وأمانة. عُرف بروحانيّة تتمحور حول الصلاة والعمل والتواضع، لا حول الظهور أمام الناس. وذكره الذين عرفوه باهتمامه بإخوته وثقته بحضور الله في تفاصيل الحياة اليوميّة. توفّي في دير القديسين قبريانوس ويوستينا في كفيفان، وأُعلن طوباويًا سنة 2010."],
    "Ignatius Maloyan": ["Born in Mardin, he entered the Armenian Catholic seminary and later studied at the monastery of Bzommar in Lebanon, an important centre of Armenian Catholic formation. He became Archbishop of Mardin in 1911 and worked to strengthen the faith and pastoral life of his people. During the persecution of 1915, he encouraged his community to remain faithful. He was beatified by Pope John Paul II in 2001.", "وُلد في ماردين، ودخل الإكليريكيّة الأرمنيّة الكاثوليكيّة، ثم تابع دراسته في دير بزمار في لبنان، وهو مركز مهمّ للتنشئة الأرمنيّة الكاثوليكيّة. أصبح رئيس أساقفة ماردين سنة 1911 وعمل على تقوية الإيمان والحياة الرعويّة لشعبه. خلال اضطهاد سنة 1915، شجّع جماعته على الثبات. أعلنه البابا يوحنا بولس الثاني طوباويًا سنة 2001."],
    "Leonard Melki": ["Youssef Habib Melki was born in Baskinta and joined the Capuchin Franciscans, taking the religious name Leonard. His ministry brought him to communities in the Ottoman lands, where he served as a missionary and educator. During the persecution of Christians in the First World War, he remained with the people entrusted to his care and died in 1915. He was beatified in 2022 with fellow Capuchin Thomas Saleh.", "وُلد يوسف حبيب ملكي في بسكنتا وانضمّ إلى الرهبنة الفرنسيسكانيّة الكبوشيّة، متّخذًا اسم ليونار. قادته خدمته إلى جماعات في أراضي الدولة العثمانيّة، حيث عمل مرسلًا ومربّيًا. خلال اضطهاد المسيحيّين في الحرب العالميّة الأولى، بقي إلى جانب الناس الذين اؤتمن على رعايتهم وتوفّي سنة 1915. أُعلن طوباويًا سنة 2022 مع الكاهن الكبوشي توما صالح."],
    "Thomas Saleh": ["After joining the Capuchins, Thomas served in mission communities in the region that is now Turkey. His ministry included preaching, education and pastoral care, often under difficult conditions. During the wartime persecution he was arrested and endured imprisonment before dying in 1917. His beatification with Leonard Melki in 2022 honoured their witness and the service of Eastern Christian clergy during a period of persecution.", "بعد انضمامه إلى الكبوشيّين، خدم توما في جماعات رسوليّة في المنطقة التي تُعرف اليوم بتركيا. شملت خدمته الوعظ والتعليم والرعاية الكهنوتيّة، وغالبًا في ظروف صعبة. خلال الاضطهاد زمن الحرب اعتُقل وتحمّل السجن قبل وفاته سنة 1917. وقد كرّم تطويبه مع ليونار ملكي سنة 2022 شهادتهما وخدمة الإكليروس المسيحي الشرقي في زمن الاضطهاد."]
  };
  for (const entry of entries) {
    const extra = expandedStories[entry.en];
    if (extra) { entry.storyEn += " " + extra[0]; entry.storyAr += " " + extra[1]; }
    if (entry.en === "Estephan El Douaihy") entry.status = "Blessed · Maronite patriarch · beatified 2024";
  }

  // Keep the Lebanon collection focused on widely recognised figures and clearly documented Church causes.
  const removeNames = new Set(["John Mark","Nilus of Egypt","Peleus","Silvanus","Tyrannio of Tyre","Zenobius of Sidon","Vulpian of Tyre","Cyril of Heliopolis","Dorotheus","Nerses I the Great","Frumentius","Leontius","Nonnus of Edessa","Theodosia of Tyre","Eudocia of Heliopolis","Pamphilus of Beirut","Christina of Tyre","Leontios of Tripoli","Hypatios of Tripoli","Theodoulos of Tripoli","The 500 Martyrs of Tyre","The 350 Disciples of Saint Maron","Marina the Monk","Béchara Abou Mrad","Yaqub Haddad","Michael the Archangel","Gabriel the Archangel","Raphael the Archangel"]);
  const deduped = new Map();
  for (const entry of entries) {
    if (removeNames.has(entry.en)) continue;
    const key = entry.en.trim().toLocaleLowerCase();
    deduped.set(key, entry);
  }
  entries.length = 0;
  entries.push(...deduped.values());
  entries.push(...[{"en":"Joseph of Nazareth","ar":"القديس يوسف خطيب مريم","letter":"J","status":"Saint · Husband of Mary · Guardian of Jesus","place":"Nazareth & Bethlehem · الناصرة وبيت لحم","years":"1st century","group":"Worldwide","storyEn":"Joseph appears in the Gospels as a descendant of David, a craftsman and the husband of Mary. When he learned that Mary was expecting a child, he chose compassion and obedience rather than public disgrace. In the Gospel narratives he receives guidance in dreams, takes Mary and the child Jesus to safety in Egypt, and later settles with them in Nazareth. Joseph is remembered for quiet faithfulness: he protects and provides for his family without seeking attention. Christians honour him as the foster father of Jesus and a model of integrity, work and care.","storyAr":"يظهر يوسف في الأناجيل من نسل داود، وكان نجّارًا وخطيب مريم. وعندما عرف أنّ مريم حبلى، اختار الرحمة والطاعة بدل التشهير بها. وفي الروايات الإنجيليّة يتلقّى الإرشاد في الأحلام، ويأخذ مريم والطفل يسوع إلى مصر طلبًا للأمان، ثم يعود ويقيم معهما في الناصرة. يُذكر يوسف بأمانته الهادئة؛ فقد حمى عائلته واعتنى بها من دون طلب الظهور. وتكرّمه الكنيسة كأب ليسوع بالتبنّي ومثال للنزاهة والعمل والرعاية."},{"en":"Peter the Apostle","ar":"القديس بطرس الرسول","letter":"P","status":"Saint · Apostle · First Pope in Catholic tradition","place":"Galilee & Rome · الجليل وروما","years":"1st century","group":"Worldwide","storyEn":"Simon, a fisherman from Galilee, was called by Jesus and given the name Peter. The Gospels show him as enthusiastic and sometimes impulsive: he professes faith in Jesus, misunderstands the path of the Cross, and denies knowing Jesus during the Passion. After the Resurrection, Jesus restores him and entrusts him with the care of the community. Peter became a leading witness in the early Church and, according to ancient Christian tradition, was martyred in Rome. Catholics regard him as the first Bishop of Rome and a foundational figure in the apostolic Church.","storyAr":"كان سمعان صيّادًا من الجليل، دعاه يسوع ومنحه اسم بطرس. وتُظهره الأناجيل متحمّسًا وأحيانًا متسرّعًا: أعلن إيمانه بيسوع، ولم يفهم طريق الصليب، وأنكر معرفته به خلال الآلام. وبعد القيامة أعاده يسوع إلى رسالته وأوكل إليه رعاية الجماعة. أصبح بطرس شاهدًا بارزًا في الكنيسة الأولى، ويقول التقليد المسيحي القديم إنّه استُشهد في روما. وتعتبره الكنيسة الكاثوليكيّة أوّل أسقف لروما وشخصيّة تأسيسيّة في الكنيسة الرسوليّة."},{"en":"Paul the Apostle","ar":"القديس بولس الرسول","letter":"P","status":"Saint · Apostle to the Gentiles","place":"Tarsus, the Eastern Mediterranean & Rome · طرسوس والشرق المتوسّطي وروما","years":"1st century","group":"Worldwide","storyEn":"Paul, first known as Saul, was a Jewish Pharisee who initially opposed the early Christian movement. According to Acts, while travelling to Damascus he experienced a profound encounter with the risen Jesus that changed the direction of his life. He became a missionary, travelling through the eastern Mediterranean and establishing Christian communities. His letters, written to guide and encourage those communities, became central texts of the New Testament. Christian tradition remembers Paul as a martyr in Rome and one of the most influential voices in the history of Christianity.","storyAr":"كان بولس، المعروف أوّلًا باسم شاول، فريسيًّا يهوديًّا عارض الحركة المسيحيّة الناشئة. وبحسب سفر أعمال الرسل، اختبر في طريقه إلى دمشق لقاءً عميقًا مع يسوع القائم غيّر مسار حياته. أصبح مرسلًا وجال في شرق البحر المتوسّط وأسّس جماعات مسيحيّة. وصارت رسائله، التي كتبها لإرشاد تلك الجماعات وتشجيعها، من النصوص الأساسيّة في العهد الجديد. ويحفظ التقليد المسيحي ذكرى استشهاده في روما، ويعتبره من أكثر الشخصيّات تأثيرًا في تاريخ المسيحيّة."},{"en":"Mary Magdalene","ar":"القديسة مريم المجدليّة","letter":"M","status":"Saint · Disciple of Jesus · Apostle to the Apostles","place":"Magdala & Jerusalem · مجدل والقدس","years":"1st century","group":"Worldwide","storyEn":"Mary Magdalene is one of the women who followed Jesus and supported his ministry. The Gospels describe her as present at the Crucifixion and among the first witnesses to the empty tomb. In John's Gospel, the risen Jesus entrusts her with the message to tell the disciples that he is alive. For this reason, Christian tradition often calls her the Apostle to the Apostles. Her story is a reminder that women were important witnesses and disciples in the earliest Christian community.","storyAr":"كانت مريم المجدليّة من النساء اللواتي تبعن يسوع وساهمن في خدمته. وتذكر الأناجيل حضورها عند الصليب، وأنّها كانت من أوائل الشهود على القبر الفارغ. وفي إنجيل يوحنّا، يكلّفها يسوع القائم بأن تنقل إلى التلاميذ خبر قيامته. لذلك يسمّيها التقليد المسيحي أحيانًا «رسولة الرسل». وتذكّرنا سيرتها بأنّ النساء كنّ شاهدات وتلميذات مهمّات في الجماعة المسيحيّة الأولى."},{"en":"John the Baptist","ar":"القديس يوحنّا المعمدان","letter":"J","status":"Saint · Prophet and Forerunner of Christ","place":"Judea & the Jordan River · اليهوديّة ونهر الأردن","years":"1st century","group":"Worldwide","storyEn":"John the Baptist preached repentance and called people to prepare for the coming of God’s kingdom. He baptised Jesus in the Jordan, an event remembered in all four Gospels. John spoke openly against injustice, including the unlawful marriage of Herod Antipas, and was imprisoned and executed. Christians honour him as the Forerunner who prepared the way for Jesus and as a prophet whose courage was rooted in his commitment to truth.","storyAr":"كرز يوحنّا المعمدان بالتوبة ودعا الناس إلى الاستعداد لمجيء ملكوت الله. وعمّد يسوع في نهر الأردن، وهو حدث تذكره الأناجيل الأربعة. وتكلّم يوحنّا بجرأة ضد الظلم، ومنه زواج هيرودس أنتيباس غير المشروع، فسُجن وأُعدم. وتكرّمه الكنيسة كسابق للمسيح هيّأ الطريق ليسوع، وكنبيّ استمدّ شجاعته من التزامه بالحق."},{"en":"Anthony of Padua","ar":"القديس أنطونيوس البدواني","letter":"A","status":"Saint · Franciscan priest and Doctor of the Church","place":"Lisbon & Padua · لشبونة وبادوفا","years":"1195–1231","group":"Worldwide","storyEn":"Born Fernando in Lisbon, Anthony first joined the Augustinian canons and became known for his learning. Inspired by the witness of Franciscan missionaries, he joined the Friars Minor and took the name Anthony. His plans to serve in Morocco changed after illness brought him to Italy, where his gift for preaching became clear. He taught Scripture, travelled to preach and served the poor. He died near Padua in 1231 and was canonised less than a year later. He is widely loved as a preacher and is often invoked by people searching for lost things.","storyAr":"وُلد أنطونيوس باسم فرناندو في لشبونة، وانضمّ أوّلًا إلى الرهبان القانونيّين الأوغسطينيّين واشتهر بعلمه. وبعد تأثّره بشهادة المرسلين الفرنسيسكانيّين، انضمّ إلى الإخوة الأصاغر واتّخذ اسم أنطونيوس. تغيّرت خطّته للخدمة في المغرب بعد مرضه وعودته إلى إيطاليا، حيث ظهرت موهبته في الوعظ. علّم الكتاب المقدّس، وجال مبشّرًا، وخدم الفقراء. توفّي قرب بادوفا سنة 1231 وأُعلن قديسًا بعد أقلّ من عام. يحبّه المؤمنون كواعظ، ويلجأ إليه كثيرون عند البحث عن الأشياء الضائعة."},{"en":"Padre Pio of Pietrelcina","ar":"القديس بادري بيو من بيتريلشينا","letter":"P","status":"Saint · Capuchin priest","place":"Pietrelcina & San Giovanni Rotondo · بيتريلشينا وسان جيوفاني روتوندو","years":"1887–1968","group":"Worldwide","storyEn":"Born Francesco Forgione in southern Italy, Padre Pio entered the Capuchin friars as a teenager and was ordained a priest in 1910. He spent most of his ministry at San Giovanni Rotondo, where people came to him for confession, spiritual counsel and prayer. He was known for a demanding life of prayer and for serving people who were sick or poor. He helped establish the Casa Sollievo della Sofferenza, a hospital opened in 1956. Pope John Paul II canonised him in 2002. His life continues to draw people interested in prayer, reconciliation and compassionate service.","storyAr":"وُلد فرنشيسكو فورجوني في جنوب إيطاليا، وانضمّ إلى الرهبنة الكبوشيّة في سنّ المراهقة ورُسم كاهنًا سنة 1910. أمضى معظم خدمته في سان جيوفاني روتوندو، حيث كان الناس يقصدونه للاعتراف والإرشاد الروحي والصلاة. عُرف بحياة صلاة جادّة وبخدمة المرضى والفقراء. وساهم في تأسيس مستشفى «بيت التخفيف من الألم» الذي افتُتح سنة 1956. أعلنه البابا يوحنا بولس الثاني قديسًا سنة 2002. وما زالت حياته تجذب المهتمّين بالصلاة والمصالحة والخدمة الرحيمة."},{"en":"Thomas Aquinas","ar":"القديس توما الأكويني","letter":"T","status":"Saint · Doctor of the Church","place":"Italy & Paris · إيطاليا وباريس","years":"1225–1274","group":"Worldwide","storyEn":"Thomas Aquinas was born into a noble family in central Italy and joined the Dominican Order despite strong family opposition. He studied and taught in Paris and several Italian cities, bringing together careful philosophical reasoning and Christian theology. His best-known work, the Summa Theologiae, offers a systematic explanation of major questions about God, creation, virtue and human life. Thomas was also devoted to prayer and the Eucharist, and composed hymns for the Church’s worship. He is remembered as one of Christianity’s most influential theologians and was declared a Doctor of the Church.","storyAr":"وُلد توما الأكويني في عائلة نبيلة في وسط إيطاليا، وانضمّ إلى الرهبنة الدومينيكيّة رغم معارضة عائلته الشديدة. درس وعلّم في باريس وعدد من المدن الإيطاليّة، وجمع بين التفكير الفلسفي الدقيق واللاهوت المسيحي. ويُعدّ كتابه الأشهر «الخلاصة اللاهوتيّة» عرضًا منظّمًا لأسئلة أساسيّة عن الله والخليقة والفضيلة والحياة الإنسانيّة. وكان توما أيضًا رجل صلاة وتعبّد للقربان المقدّس، وكتب تراتيل لليتورجيا. ويُذكر كأحد أكثر لاهوتيي المسيحيّة تأثيرًا وأُعلن معلّمًا للكنيسة."},{"en":"Dominic de Guzmán","ar":"القديس دومينيك","letter":"D","status":"Saint · Founder of the Order of Preachers","place":"Caleruega & Toulouse · كاليروغا وتولوز","years":"c. 1170–1221","group":"Worldwide","storyEn":"Dominic was born in Castile, Spain, and became a priest known for preaching and a life of simplicity. During journeys in southern France he saw the need for clear teaching, patient dialogue and a community dedicated to study and evangelisation. He gathered companions and founded the Order of Preachers, later known as the Dominicans. The order became influential in education, preaching and theology. Dominic is remembered for joining intellectual preparation with compassion and a disciplined life of prayer.","storyAr":"وُلد دومينيك في قشتالة بإسبانيا، وأصبح كاهنًا عُرف بالوعظ وبالحياة البسيطة. وخلال رحلاته في جنوب فرنسا رأى الحاجة إلى تعليم واضح وحوار صبور وجماعة مكرّسة للدراسة والبشارة. جمع رفاقًا وأسّس رهبنة الوعّاظ التي عُرفت لاحقًا بالدومينيكان. وكان للرهبنة تأثير كبير في التعليم والوعظ واللاهوت. ويُذكر دومينيك لجمعه بين الاستعداد الفكري والرحمة ونظام حياة الصلاة."},{"en":"Joan of Arc","ar":"القديسة جان دارك","letter":"J","status":"Saint · French national heroine","place":"Domrémy & Rouen · دومريمي وروان","years":"c. 1412–1431","group":"Worldwide","storyEn":"Joan was born to a farming family in Domrémy, France, during the Hundred Years’ War. As a teenager she believed she was being called to help the French people and the future King Charles VII. She travelled to meet him and became a symbolic figure in the campaign that lifted the siege of Orléans in 1429. Captured by the English and their allies, she was tried by an ecclesiastical court and executed in 1431. The trial was later declared invalid, and she was canonised in 1920. Her story is remembered for conviction, courage and the importance of a fair process.","storyAr":"وُلدت جان في عائلة زراعيّة في دومريمي بفرنسا خلال حرب المئة عام. وفي سنّ المراهقة اعتقدت أنّها مدعوّة لمساعدة الشعب الفرنسي والملك المستقبلي شارل السابع. سافرت لمقابلته وأصبحت رمزًا في الحملة التي رفعت حصار أورليان سنة 1429. أُسرت على يد الإنجليز وحلفائهم، وحوكمت أمام محكمة كنسيّة وأُعدمت سنة 1431. أُعلن بطلان المحاكمة لاحقًا، وأُعلنت قديسة سنة 1920. وتُذكر قصّتها للإيمان بالقضيّة والشجاعة وأهميّة العدالة."},{"en":"Bernadette Soubirous","ar":"القديسة برناديت سوبيرو","letter":"B","status":"Saint · Witness of Lourdes","place":"Lourdes, France · لورد، فرنسا","years":"1844–1879","group":"Worldwide","storyEn":"Bernadette was born into a poor family in Lourdes. In 1858, while still a teenager, she reported a series of experiences at the grotto of Massabielle that drew visitors and Church investigation. She remained simple and reserved despite the attention, later entering the Sisters of Charity at Nevers. Her life in the convent was marked by prayer and illness rather than public fame. The shrine at Lourdes became one of the world’s best-known pilgrimage sites, and Bernadette was canonised in 1933.","storyAr":"وُلدت برناديت في عائلة فقيرة في مدينة لورد. سنة 1858، وكانت لا تزال مراهقة، تحدّثت عن سلسلة من الاختبارات الروحيّة في مغارة ماسابييل، ما جذب الزوّار وفتح تحقيقًا كنسيًّا. بقيت بسيطة ومتحفّظة رغم الاهتمام الكبير، ثم دخلت راهبات المحبّة في نيفير. وتميّزت حياتها في الدير بالصلاة والمرض لا بالشهرة. وأصبح مزار لورد من أشهر أماكن الحج في العالم، وأُعلنت برناديت قديسة سنة 1933."},{"en":"Rita of Cascia","ar":"القديسة ريتا من كاشيا","letter":"R","imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/S.Rita_da_Cascia.jpg?width=700","imagePage":"https://commons.wikimedia.org/wiki/File:S.Rita_da_Cascia.jpg","status":"Saint · Augustinian nun","place":"Roccaporena & Cascia · روكّابورينا وكاشيا","years":"c. 1381–1457","group":"Worldwide","storyEn":"Margherita Lotti, known as Rita, was born in 1381 in Roccaporena, near Cascia in Umbria, central Italy. Her parents were known locally as peacemakers who helped settle disputes between rival families, and they raised their daughter in the Christian faith. Rita learned to pray and developed a particular devotion to Saint Augustine, Saint John the Baptist and Saint Nicholas of Tolentino. As a young woman, she married Paolo di Ferdinando Mancini and became the mother of two sons. The period was marked by bitter family and political rivalries. According to the traditional accounts of her life, Rita patiently encouraged her husband to turn away from violence and toward a more peaceful Christian life. When he was murdered in a feud, she chose forgiveness rather than revenge. She feared that her sons might be drawn into retaliation and prayed that the cycle of hostility would end. After both sons died, Rita gradually devoted herself more fully to prayer and service. She asked to enter the Augustinian monastery of Saint Mary Magdalene in Cascia. Her request was reportedly refused several times because of the tensions surrounding her family, but after reconciliation between the feuding families she was admitted and received the religious name Rita. For about forty years she lived as an Augustinian nun, dedicating herself to prayer, humility, care for her sisters and works of charity. The tradition of the dry vine that grew after she obediently watered it is remembered at the monastery as a sign of her humility. In 1432, while praying before a crucifix and meditating on Christ’s Passion, she received a wound on her forehead that tradition associates with a thorn from Christ’s crown; it remained with her for many years. Near the end of her life, while seriously ill, she is associated with the well-known story of the winter rose and figs found in her family garden at her request. Rita died in Cascia in May 1457. Devotion to her spread soon after her death, and she was beatified by Pope Urban VIII in 1626 and canonised by Pope Leo XIII on 24 May 1900. Catholics especially invoke her in difficult situations, but the heart of her witness is forgiveness, reconciliation, perseverance and faithful love in ordinary life.","storyAr":"وُلدت مارغريتا لوتّي، المعروفة باسم ريتا، سنة 1381 في روكّابورينا قرب كاشيا في أومبريا بوسط إيطاليا. وكان والداها معروفَين بمساعيهما للصلح بين العائلات المتخاصمة، وربّيا ابنتهما على الإيمان المسيحي والصلاة. وتعلّمت ريتا محبّة القديس أغسطينوس والقديس يوحنا المعمدان والقديس نقولا التولنتيني. تزوّجت في شبابها باولو دي فرديناندو مانشيني وأصبحت أمًّا لولدين. وكانت تلك المرحلة مليئة بالخلافات العائلية والسياسية. وبحسب الروايات التقليدية عن حياتها، شجّعت زوجها بصبر على الابتعاد عن العنف والسير في طريق أكثر سلامًا. وعندما قُتل في نزاع بين العائلات، اختارت الغفران بدل الانتقام. وخافت أن ينجرف ابناها إلى دوّامة الثأر، فصلّت كي تنتهي الخصومات. وبعد وفاة ابنيها، اتجهت تدريجيًا إلى حياة أعمق من الصلاة والخدمة. طلبت الدخول إلى دير القديسة مريم المجدلية للأوغسطينيات في كاشيا، لكن طلبها رُفض مرّات بحسب التقليد بسبب التوترات العائلية المحيطة بها. وبعد حصول المصالحة بين العائلات، قُبلت في الدير واتخذت اسم ريتا. أمضت نحو أربعين سنة راهبة أوغسطينية، مكرّسة حياتها للصلاة والتواضع وخدمة أخواتها وأعمال المحبة. وتُحفظ في تقاليد الدير رواية الغصن اليابس الذي نما بعدما أطاعَت ريتا واعتنت به، علامةً على تواضعها. سنة 1432، وبينما كانت تصلّي أمام الصليب وتتأمّل آلام المسيح، ظهرت على جبينها جراحة ربطها التقليد بشوكة من إكليل المسيح، وبقي أثرها سنوات طويلة. وقبيل وفاتها، وهي مريضة، ارتبط اسمها برواية الوردة والتين اللذين طُلب إحضارهما من حديقة بيت عائلتها في فصل الشتاء. رقدت ريتا في كاشيا في أيار 1457. وانتشر إكرامها بعد وفاتها، وأعلنها البابا أوربانوس الثامن طوباوية سنة 1626، ثم أعلنها البابا لاون الثالث عشر قديسة في 24 أيار 1900. ويلجأ إليها المؤمنون خصوصًا في الظروف الصعبة، لكن جوهر شهادتها هو الغفران والمصالحة والصبر والمحبة الأمينة في الحياة اليومية."},{"en":"Maria Faustina Kowalska","ar":"القديسة فوستينا كوفالسكا","letter":"M","status":"Saint · Apostle of Divine Mercy","place":"Poland · بولندا","years":"1905–1938","group":"Worldwide","storyEn":"Born Helena Kowalska in Poland, Faustina entered the Congregation of the Sisters of Our Lady of Mercy and served in several convents. Her diary records her spiritual life and her devotion to the mercy of God. The message associated with her became widely known through the Divine Mercy image, the Chaplet and the celebration of Divine Mercy Sunday. Her writings are read by Catholics around the world, while her own religious life was marked by ordinary duties, prayer and service. Pope John Paul II canonised her in 2000.","storyAr":"وُلدت هيلينا كوفالسكا في بولندا، ودخلت جمعيّة راهبات سيّدة الرحمة وخدمت في أديرة عدّة. يسجّل دفترها حياتها الروحيّة وتعبّدها لرحمة الله. وانتشرت الرسالة المرتبطة بها من خلال صورة الرحمة الإلهيّة، وورديّة الرحمة، والاحتفال بأحد الرحمة الإلهيّة. تُقرأ كتاباتها لدى الكاثوليك في أنحاء العالم، فيما تميّزت حياتها الرهبانيّة بالأعمال اليوميّة والصلاة والخدمة. أعلنها البابا يوحنا بولس الثاني قديسة سنة 2000."},{"en":"Francis de Sales","ar":"القديس فرنسيس دي سال","letter":"F","status":"Saint · Bishop and Doctor of the Church","place":"Savoy & Geneva · سافوا وجنيف","years":"1567–1622","group":"Worldwide","storyEn":"Francis de Sales was born in Savoy and studied law before choosing priesthood. As a bishop, he worked to renew Christian life through patient teaching, personal guidance and clear writing. He believed that holiness was possible in every state of life, not only in monasteries, and expressed this in his well-known book Introduction to the Devout Life. With Jane Frances de Chantal he founded the Order of the Visitation. He is remembered as a model of gentleness, communication and pastoral care.","storyAr":"وُلد فرنسيس دي سال في سافوا ودرس القانون قبل أن يختار الكهنوت. وبصفته أسقفًا، عمل على تجديد الحياة المسيحيّة من خلال التعليم الصبور والإرشاد الشخصي والكتابة الواضحة. آمن بأنّ القداسة ممكنة في كلّ حالات الحياة، لا في الأديرة فقط، وشرح ذلك في كتابه المعروف «مدخل إلى الحياة التقويّة». وأسّس مع جان فرنسواز دو شانتال رهبنة الزيارة. ويُذكر مثالًا للوداعة والتواصل والرعاية الرعويّة."},{"en":"Jerome","ar":"القديس إيرونيموس","letter":"J","status":"Saint · Doctor of the Church","place":"Dalmatia, Bethlehem & Rome · دالماتيا وبيت لحم وروما","years":"c. 347–420","group":"Worldwide","storyEn":"Jerome was a gifted biblical scholar who learned Hebrew and Greek and devoted much of his life to studying Scripture. At the request of Pope Damasus, he undertook a Latin translation of the Bible that became known as the Vulgate and shaped Western Christianity for centuries. He spent his later years in Bethlehem, where he taught, wrote commentaries and supported a community of pilgrims and religious women. Jerome is remembered for his scholarship, strong character and conviction that Christians should know the Scriptures deeply.","storyAr":"كان إيرونيموس عالمًا موهوبًا في الكتاب المقدّس، تعلّم العبريّة واليونانيّة وكرّس جزءًا كبيرًا من حياته لدراسة الأسفار المقدّسة. وبطلب من البابا داماسوس، أنجز ترجمة لاتينيّة للكتاب المقدّس عُرفت باسم الفولغاتا وأثّرت في المسيحيّة الغربيّة قرونًا طويلة. أمضى سنواته الأخيرة في بيت لحم، حيث علّم وكتب شروحًا كتابيّة وساعد جماعة من الحجّاج والنساء المتعبّدات. ويُذكر بعلمه وقوّة شخصيّته وإيمانه بضرورة معرفة المسيحيّين للكتاب المقدّس بعمق."},{"en":"Michael the Archangel","ar":"رئيس الملائكة ميخائيل","letter":"M","status":"Archangel · Honoured in Christian tradition","place":"Heavenly host · الملائكة","years":"Biblical tradition","group":"Worldwide","storyEn":"Michael is named in the Book of Daniel, the Letter of Jude and the Book of Revelation. Christian tradition understands him as a chief angel who stands for faithfulness to God and protection against evil. He is often depicted as a warrior angel, but the central meaning of his biblical role is service to God rather than personal power. Churches across many Christian traditions are dedicated to him, and his feast is celebrated with Gabriel and Raphael on 29 September in the Roman calendar.","storyAr":"يَرِد اسم ميخائيل في سفر دانيال ورسالة يهوذا وسفر الرؤيا. ويفهمه التقليد المسيحي كرئيس للملائكة يرمز إلى الأمانة لله والحماية من الشر. وغالبًا ما يُصوَّر كملاك محارب، لكنّ المعنى الأساسي لدوره الكتابي هو خدمة الله لا القوّة الشخصيّة. وقد خُصّصت كنائس كثيرة في تقاليد مسيحيّة متنوّعة لإكرامه، ويُحتفل بتذكاره مع جبرائيل ورفائيل في 29 أيلول في التقويم الروماني."},{"en":"Gabriel the Archangel","ar":"رئيس الملائكة جبرائيل","letter":"G","status":"Archangel · Messenger of God","place":"Biblical tradition · التقليد الكتابي","years":"Biblical tradition","group":"Worldwide","storyEn":"Gabriel appears in the Book of Daniel as a messenger who helps explain visions. In the Gospel of Luke, he announces to Zechariah the birth of John the Baptist and brings Mary the message that she will become the mother of Jesus. For this reason Gabriel is especially associated with the Annunciation and with the role of carrying God’s message. Christians honour him as an archangel and a symbol of hope, clarity and faithful service.","storyAr":"يظهر جبرائيل في سفر دانيال رسولًا يساعد على تفسير الرؤى. وفي إنجيل لوقا يبشّر زكريّا بميلاد يوحنّا المعمدان، ثم يحمل إلى مريم البشارة بأنّها ستصير أمّ يسوع. لذلك يرتبط جبرائيل خصوصًا بالبشارة وبمهمّة نقل رسالة الله. وتكرّمه الكنيسة كرئيس ملائكة ورمز للرجاء والوضوح والخدمة الأمينة."},{"en":"Raphael the Archangel","ar":"رئيس الملائكة رافائيل","letter":"R","status":"Archangel · Companion and healer in Tobit","place":"Book of Tobit · سفر طوبيا","years":"Biblical tradition","group":"Worldwide","storyEn":"Raphael is a central figure in the Book of Tobit, where he accompanies the young Tobias on a journey while concealing his angelic identity. He guides and protects Tobias, helps bring healing to the family and finally reveals that he is one of the angels who stand before God. Christian tradition honours Raphael as a companion for travellers and a sign of God’s healing care. His feast is celebrated with Michael and Gabriel on 29 September in the Roman calendar.","storyAr":"يُعدّ رافائيل شخصيّة أساسيّة في سفر طوبيا، حيث يرافق طوبيا الشاب في رحلة من دون أن يكشف هويّته الملائكيّة. يرشد طوبيا ويحميه ويساعد على شفاء العائلة، ثم يكشف أنّه أحد الملائكة الواقفين أمام الله. ويكرّمه التقليد المسيحي رفيقًا للمسافرين وعلامة على عناية الله الشافية. ويُحتفل بتذكاره مع ميخائيل وجبرائيل في 29 أيلول في التقويم الروماني."},{"en":"Stephen the Protomartyr","ar":"القديس إسطفانوس أوّل الشهداء","letter":"S","status":"Saint · First Christian martyr","place":"Jerusalem · أورشليم","years":"1st century","group":"Worldwide","storyEn":"Stephen was one of the seven appointed to serve the early Christian community in Jerusalem. The Acts of the Apostles describes him as full of faith and wisdom, speaking publicly about Jesus and the Scriptures. His preaching led to a confrontation with religious authorities, and he was stoned to death. As he died, the account says he prayed for those who were killing him. The Church calls him the Protomartyr—the first Christian martyr—and remembers his witness on 26 December.","storyAr":"كان إسطفانوس واحدًا من السبعة الذين اختيروا لخدمة الجماعة المسيحيّة الأولى في أورشليم. ويصفه سفر أعمال الرسل بأنّه ممتلئ إيمانًا وحكمة، وكان يتكلّم علنًا عن يسوع والكتب المقدّسة. أدّى وعظه إلى مواجهة مع السلطات الدينيّة، فرُجم حتى الموت. وتقول الرواية إنّه صلّى من أجل الذين كانوا يقتلونه. وتدعوه الكنيسة أوّل الشهداء المسيحيّين، وتحتفل بتذكاره في 26 كانون الأوّل."},{"en":"Lawrence of Rome","ar":"القديس لورنسيوس","letter":"L","status":"Saint · Deacon and martyr","place":"Rome · روما","years":"Died 258","group":"Worldwide","storyEn":"Lawrence served as a deacon in the Church of Rome during the persecution under Emperor Valerian. Ancient Christian accounts remember him for caring for the poor and for his courageous response when authorities demanded the Church’s treasures: he presented the poor and vulnerable as the Church’s true treasure. He was executed in 258 and became one of Rome’s most venerated early martyrs. His story links Christian worship with practical care for people in need.","storyAr":"خدم لورنسيوس شماسًا في كنيسة روما خلال الاضطهاد في عهد الإمبراطور فاليريان. وتذكره الروايات المسيحيّة القديمة باهتمامه بالفقراء وبجوابه الشجاع عندما طالبت السلطات بكنوز الكنيسة؛ إذ قدّم الفقراء والمحتاجين بوصفهم كنز الكنيسة الحقيقي. أُعدم سنة 258 وأصبح من أكثر شهداء روما الأوائل إكرامًا. وتربط سيرته بين العبادة المسيحيّة والعناية العمليّة بالمحتاجين."},{"en":"Louis IX of France","ar":"القديس لويس التاسع ملك فرنسا","letter":"L","status":"Saint · King of France","place":"France & North Africa · فرنسا وشمال أفريقيا","years":"1214–1270","group":"Worldwide","storyEn":"Louis IX became King of France as a child and ruled for decades, seeking to connect public responsibility with Christian faith. He supported hospitals, cared for people who were poor and sick, and was known for hearing petitions personally. His reign also included crusading campaigns, which should be understood within the complex history of the medieval period rather than romanticised. He died during a campaign in North Africa and was canonised in 1297. He is remembered for charity, justice and the responsibilities of leadership.","storyAr":"أصبح لويس التاسع ملكًا على فرنسا وهو طفل، وحكم عقودًا ساعيًا إلى ربط مسؤوليّة الحكم بالإيمان المسيحي. دعم المستشفيات واهتمّ بالفقراء والمرضى، وعُرف باستماعه إلى شكاوى الناس بنفسه. وشهد عهده أيضًا حملات صليبيّة ينبغي فهمها ضمن تاريخ العصور الوسطى المعقّد لا تمجيدها. توفّي خلال حملة في شمال أفريقيا وأُعلن قديسًا سنة 1297. ويُذكر بأعمال الرحمة والعدل ومسؤوليّة القيادة."},{"en":"Edith Stein (Teresa Benedicta of the Cross)","ar":"القديسة إديث شتاين (تريزا بنديكتا للصليب)","letter":"E","status":"Saint · Carmelite nun and martyr","place":"Germany, the Netherlands & Auschwitz · ألمانيا وهولندا وأوشفيتز","years":"1891–1942","group":"Worldwide","storyEn":"Edith Stein was born into a Jewish family in Breslau and became a philosopher known for her work on empathy and human personhood. After years of intellectual searching, she became Catholic and later entered the Discalced Carmelite Order, taking the name Teresa Benedicta of the Cross. Under Nazi persecution she was arrested with other Jewish Christians and deported to Auschwitz, where she was killed in 1942. The Church honours her as a martyr and a patron of Europe, while remembering her Jewish roots and the tragedy of the Holocaust.","storyAr":"وُلدت إديث شتاين في عائلة يهوديّة في بريسلاو، وأصبحت فيلسوفة عُرفت بأبحاثها حول التعاطف وكرامة الإنسان. وبعد سنوات من البحث الفكري اعتنقت الكاثوليكيّة، ثم دخلت الرهبنة الكرمليّة الحافية واتّخذت اسم تريزا بنديكتا للصليب. خلال الاضطهاد النازي اعتُقلت مع مسيحيّين من أصل يهودي ورُحّلت إلى أوشفيتز حيث قُتلت سنة 1942. تكرّمها الكنيسة شهيدة وشفيعة لأوروبا، مع حفظ جذورها اليهوديّة وذكرى مأساة المحرقة."}]);
  // Archangels are honoured in Christian tradition, but are not human saints; keep this directory focused on saints.
  for (const angel of ["Michael the Archangel", "Gabriel the Archangel", "Raphael the Archangel"]) {
    const index = entries.findIndex(entry => entry.en === angel);
    if (index >= 0) entries.splice(index, 1);
  }

  const detailedLebanese = {"Aquilina of Byblos":["Aquilina is remembered as a young Christian from Byblos who bore witness to her faith during the Roman persecutions. Her feast is associated with 13 June, and her name remains part of the Christian memory of Jbeil. The details of her martyrdom come from ancient accounts rather than modern records, but her local identity is clear: she is one of the best-known early Christian figures linked with Byblos.","تُذكر أكويلينا كشابّة مسيحيّة من جبيل شهدت لإيمانها خلال الاضطهادات الرومانيّة. يرتبط تذكارها بتاريخ 13 حزيران، وما زال اسمها حاضرًا في الذاكرة المسيحيّة لمدينة جبيل. وتأتي تفاصيل استشهادها من روايات قديمة لا من سجلات حديثة، لكنّ ارتباطها المحلي واضح؛ فهي من أبرز الشخصيّات المسيحيّة الأولى المرتبطة بجبيل."],"Barbara":["Barbara is among the most popular saints in Lebanon, where her feast on 4 December is celebrated in homes, schools and parishes. Christian tradition tells of a young woman who embraced the faith despite opposition from her father and who became a witness to courage and fidelity. The familiar customs of the feast—including children dressing up and visiting neighbours—have become part of Lebanese cultural life. The earliest historical details of her life are uncertain, so the story is presented as a widely loved Christian tradition.","تُعدّ بربارة من أكثر القديسات شهرة في لبنان، ويُحتفل بعيدها في 4 كانون الأوّل في البيوت والمدارس والرعايا. يروي التقليد المسيحي قصّة شابّة اعتنقت الإيمان رغم معارضة والدها، وأصبحت مثالًا للشجاعة والأمانة. كما أصبحت عادات العيد المعروفة، ومنها تنكّر الأطفال وزيارة الجيران، جزءًا من الحياة الثقافيّة اللبنانيّة. أمّا التفاصيل التاريخيّة الأولى لسيرتها فغير مؤكّدة، لذلك تُعرض قصّتها كتقليد مسيحي محبوب وواسع الانتشار."],"Estephan El Douaihy":["Born in Ehden in 1630, Estephan El Douaihy was recognised early for his intelligence and sent to the Maronite College in Rome. He returned to the East, served as a priest and bishop, and was elected Maronite Patriarch in 1670. He became one of the most important historians of the Maronite Church, preserving its liturgy, music, manuscripts and memory during a difficult era. His writings remain valuable sources for Lebanese and Middle Eastern church history. He was beatified in Bkerké on 2 August 2024; his correct title is Blessed, not Saint.","وُلد إسطفان الدويهي في إهدن سنة 1630، ولاحظ المحيطون به ذكاءه منذ الصغر فأُرسل إلى المدرسة المارونيّة في روما. عاد إلى الشرق وخدم كاهنًا وأسقفًا، ثم انتُخب بطريركًا مارونيًا سنة 1670. أصبح من أهم مؤرّخي الكنيسة المارونيّة، إذ حفظ ليتورجيتها وموسيقاها ومخطوطاتها وذاكرتها في حقبة صعبة. وما زالت كتاباته مصادر مهمّة لتاريخ الكنيسة في لبنان والشرق الأوسط. أُعلن طوباويًا في بكركي في 2 آب 2024؛ ولقبه الصحيح طوباوي لا قديس مُعلن."],"Ignatius Maloyan":["Ignatius Maloyan was born in Mardin in 1869 and became an Armenian Catholic priest. He studied at the Bzommar seminary in Lebanon, was ordained in 1896 and served Armenian Catholic communities before becoming Archbishop of Mardin in 1911. During the persecution of 1915, he encouraged his people to remain faithful and refused to abandon his community. He was killed in 1915, beatified by Pope John Paul II in 2001 and canonised by Pope Leo XIV on 19 October 2025. He is included as an important Eastern Christian figure with a strong connection to Lebanon through his formation at Bzommar.","وُلد إغناطيوس مالويان في ماردين سنة 1869 وأصبح كاهنًا أرمنيًا كاثوليكيًا. درس في إكليريكيّة بزمار في لبنان، ورُسم كاهنًا سنة 1896 وخدم جماعات أرمنيّة كاثوليكيّة قبل أن يصبح رئيس أساقفة ماردين سنة 1911. خلال اضطهاد سنة 1915، شجّع أبناء رعيّته على الثبات ورفض التخلّي عن جماعته. قُتل سنة 1915، وأعلنه البابا يوحنا بولس الثاني طوباويًا سنة 2001، ثم أعلنه البابا لاون الرابع عشر قديسًا في 19 تشرين الأوّل 2025. أُدرج كشخصيّة مسيحيّة شرقيّة مهمّة ترتبط بلبنان من خلال تنشئته في بزمار."],"Nimatullah Al-Hardini":["Youssef Kassab was born in Hardine in North Lebanon in 1808. He entered the Lebanese Maronite Order as a young man and took the name Nimatullah. He served his community through prayer, teaching, monastic leadership and the careful restoration of liturgical books. He spent much of his life in the monastery of Kfifan, where he became known for humility, patience and devotion to the Eucharist. The young Charbel Makhlouf was among those influenced by his example. Nimatullah died in 1858 and was canonised by Pope John Paul II in 2004.","وُلد يوسف كسّاب في حردين في شمال لبنان سنة 1808. دخل الرهبنة اللبنانيّة المارونيّة شابًا واتّخذ اسم نعمة الله. خدم جماعته بالصلاة والتعليم والمسؤوليّات الرهبانيّة والعناية بترميم الكتب الليتورجيّة. أمضى قسمًا كبيرًا من حياته في دير كفيفان، حيث عُرف بالتواضع والصبر والتعبّد للقربان المقدّس. وكان شربل مخلوف الشاب من الذين تأثّروا بمثاله. توفّي نعمة الله سنة 1858 وأعلنه البابا يوحنا بولس الثاني قديسًا سنة 2004."],"Rafqa Pietra Choboq Ar-Rayès":["Rafqa was born in Himlaya in 1832 and was baptised Boutroussieh. After a difficult childhood and the loss of her mother, she discerned a religious vocation and entered the Mariamette Congregation, serving as a teacher and catechist. She later joined the Lebanese Maronite Order and lived at the monastery of Saint Joseph in Jrabta. Her life became a witness to prayer, patience and trust in God through prolonged illness. She died in 1914, was beatified in 1985 and canonised by Pope John Paul II in 2001.","وُلدت رفقا في حِملايا سنة 1832 واعتمدت باسم بطرسيّة. بعد طفولة صعبة وفقدان والدتها، ميّزت دعوتها الرهبانيّة ودخلت جمعيّة المريميّات، حيث خدمت معلّمة ومرشدة في التعليم المسيحي. ثم انضمّت إلى الرهبنة اللبنانيّة المارونيّة وعاشت في دير مار يوسف في جربتا. أصبحت حياتها شهادة للصلاة والصبر والثقة بالله خلال مرض طويل. توفّيت سنة 1914، وأُعلنت طوباويّة سنة 1985 وقديسة على يد البابا يوحنا بولس الثاني سنة 2001."],"Estephan Nehme":["Estephan Nehme was born in Lehfed in 1889 and entered the Lebanese Maronite Order as a young man. He lived in several monasteries, carrying out ordinary work with care and treating his fellow monks with patience and kindness. His spirituality joined prayer with manual labour and a deep respect for the daily duties of community life. He died at Kfifan in 1938 and was beatified by Pope Benedict XVI in 2010. His story is especially meaningful because it shows holiness expressed through ordinary work, humility and consistency.","وُلد إسطفان نعمة في لحفد سنة 1889 ودخل الرهبنة اللبنانيّة المارونيّة شابًا. عاش في أديرة عدّة، وأدّى الأعمال اليوميّة بعناية وعامل إخوته الرهبان بصبر ولطف. جمعت روحانيّته بين الصلاة والعمل اليدوي واحترام واجبات الحياة الجماعيّة. توفّي في كفيفان سنة 1938 وأعلنه البابا بندكتس السادس عشر طوباويًا سنة 2010. وتكمن أهميّة سيرته في أنّها تُظهر القداسة من خلال العمل العادي والتواضع والثبات."],"Leonard Melki":["Youssef Habib Melki was born in Baskinta in 1881 and joined the Capuchin Franciscans, taking the name Leonard. He served as a missionary and educator among Christian communities in the Ottoman Empire, including in the region of Mardin. During the persecution of 1915 he was arrested and killed because of his faith and ministry. His remains and memory became a sign of the suffering of Eastern Christians during that period. Pope Francis recognised his martyrdom and he was beatified in 2022 together with Thomas Saleh.","وُلد يوسف حبيب ملكي في بسكنتا سنة 1881 وانضمّ إلى الرهبنة الفرنسيسكانيّة الكبوشيّة، متّخذًا اسم ليونار. خدم مرسلًا ومربّيًا بين الجماعات المسيحيّة في الدولة العثمانيّة، ومنها منطقة ماردين. خلال اضطهاد سنة 1915 اعتُقل وقُتل بسبب إيمانه وخدمته. وأصبحت ذكراه علامة على آلام مسيحيّي الشرق في تلك المرحلة. اعترف البابا فرنسيس باستشهاده وأُعلن طوباويًا سنة 2022 مع توما صالح."],"Thomas Saleh":["Gerges Hanna Saleh was born in Baabdat in 1879 and became a Capuchin Franciscan priest. He served in mission communities in the Ottoman lands, especially among people who needed pastoral care and education. During the persecution of Christians in the First World War, he was arrested and imprisoned; he died in 1917. His witness is remembered alongside that of Leonard Melki, and both were beatified in 2022. His life represents the service of Lebanese clergy beyond Lebanon and their solidarity with vulnerable communities.","وُلد جرجس حنّا صالح في بعبدات سنة 1879 وأصبح كاهنًا فرنسيسكانيًا كبوشيًا. خدم في جماعات رسوليّة في الأراضي العثمانيّة، ولا سيّما بين الذين احتاجوا إلى الرعاية الكهنوتيّة والتعليم. خلال اضطهاد المسيحيّين في الحرب العالميّة الأولى اعتُقل وسُجن، وتوفّي سنة 1917. وتُذكر شهادته إلى جانب شهادة ليونار ملكي، وقد أُعلن الاثنان طوباويّين سنة 2022. وتمثّل حياته خدمة الإكليروس اللبناني خارج لبنان وتضامنه مع الجماعات الضعيفة."],"The Massabki Brothers":["Francis, Abdel Moati and Raphael Massabki were Maronite laymen from a Lebanese family living in Damascus. They are remembered for remaining faithful to Christianity during the persecution of July 1860. Their witness was not that of clergy or public leaders, but of brothers whose faith shaped ordinary family and community life. Pope Francis canonised the three brothers together on 20 October 2024. Their feast is celebrated on 10 July, and their story connects Lebanese Maronite history with the wider Christian history of Damascus.","كان فرنسيس وعبد المعطي ورفائيل المسابكي علمانيّين موارنة من عائلة لبنانيّة عاشت في دمشق. وتُكرّمهم الكنيسة لثباتهم في الإيمان المسيحي خلال اضطهاد تموز 1860. لم تكن شهادتهم شهادة رجال دين أو قادة عامّين، بل شهادة إخوة شكّل الإيمان حياتهم العائليّة والجماعيّة. أعلن البابا فرنسيس الإخوة الثلاثة قديسين معًا في 20 تشرين الأول 2024. ويُحتفل بتذكارهم في 10 تموز، وتربط قصّتهم تاريخ الموارنة في لبنان بتاريخ المسيحيّة الأوسع في دمشق."],"Maron":["Saint Maron was a Syriac-speaking Christian monk and hermit whose life of prayer in the late fourth and early fifth centuries inspired a wide spiritual movement. His disciples formed communities that became known as Maronites, and the tradition associated with him eventually developed into the Maronite Church. Although the historical details of his life are limited, his influence on the spiritual identity of the Maronite people is profound. His feast is celebrated on 9 February, and he remains a central figure in the history of the Church in Lebanon and the Middle East.","كان مارون راهبًا وناسكًا مسيحيًا ناطقًا بالسريانيّة، ألهمت حياته النسكيّة في أواخر القرن الرابع ومطلع الخامس حركة روحيّة واسعة. أسّس تلاميذه جماعات عُرفت بالموارنة، وتطوّر التقليد المرتبط به مع الزمن إلى الكنيسة المارونيّة. ورغم محدوديّة التفاصيل التاريخيّة عن حياته، فإنّ تأثيره في الهويّة الروحيّة للشعب الماروني عميق. يُحتفل بعيده في 9 شباط، وما زال شخصيّة محوريّة في تاريخ الكنيسة في لبنان والشرق الأوسط."],"John Maron":["John Maron is remembered in Maronite tradition as the first Maronite patriarch and a key figure in the early organisation of the Maronite Church. He served during a period of political and theological conflict in the region and is associated with Kfarhay in North Lebanon, where his monastery and shrine preserve his memory. The surviving accounts were written later and some details remain debated by historians, but his importance in Maronite ecclesial memory is enduring. He is honoured as a saint in the Maronite tradition.","يُذكر يوحنا مارون في التقليد الماروني بوصفه أوّل بطريرك ماروني وشخصيّة أساسيّة في التنظيم المبكر للكنيسة المارونيّة. خدم في فترة صراعات سياسيّة ولاهوتيّة في المنطقة، ويرتبط اسمه بكفرحي في شمال لبنان، حيث يحفظ ديره ومزاره ذكراه. كُتبت الروايات المتبقيّة في زمن لاحق، ولا تزال بعض التفاصيل موضع نقاش تاريخي، لكنّ مكانته في الذاكرة الكنسيّة المارونيّة ثابتة. ويُكرَّم قديسًا في التقليد الماروني."],"Elias Hoayek":["Elias Hoayek was born in Helta in the Batroun district in 1843. After studying in Lebanon and Rome, he became a priest and later the 72nd Maronite Patriarch in 1899. His leadership covered famine, the First World War and the birth of modern Lebanon. He co-founded the Congregation of the Maronite Sisters of the Holy Family and advocated for the establishment of Greater Lebanon in 1920. He is remembered for opening church institutions to people suffering hunger and displacement, regardless of religion. He was beatified in Dimane on 25 July 2026 after the Church recognised a miracle attributed to his intercession.","وُلد الياس الحويّك في حلتا بقضاء البترون سنة 1843. بعد دراسته في لبنان وروما، أصبح كاهنًا ثم البطريرك الماروني الثاني والسبعين سنة 1899. شملت قيادته المجاعة والحرب العالميّة الأولى وولادة لبنان الحديث. شارك في تأسيس جمعيّة راهبات العائلة المقدّسة المارونيّات، ودافع عن قيام لبنان الكبير سنة 1920. ويُذكر لفتحه المؤسّسات الكنسيّة أمام الجائعين والمهجّرين من دون تمييز ديني. أُعلن طوباويًا في الديمان في 25 تموز 2026 بعد الاعتراف بأعجوبة منسوبة إلى شفاعته."],"Blessed Jacques Haddad (Abouna Yaacoub)":["Khalil Haddad was born in Ghazir in 1875. After studying in Lebanon, he joined the Capuchin Franciscans and took the name Jacques. He became known as Abouna Yaacoub for his preaching, care for poor families and service to people who were sick, abandoned or without support. He founded the Franciscan Sisters of the Cross and established institutions that grew into hospitals and social-care centres. He was beatified in 2008 and remains one of Lebanon’s best-known modern religious figures.","وُلد خليل الحداد في غزير سنة 1875. بعد دراسته في لبنان، انضمّ إلى الرهبنة الفرنسيسكانيّة الكبوشيّة واتّخذ اسم يعقوب. عُرف باسم الأب يعقوب بفضل وعظه واهتمامه بالعائلات الفقيرة وخدمته للمرضى والمتروكين ومن لا سند لهم. أسّس جمعيّة راهبات الصليب الفرنسيسكانيّات وأقام مؤسّسات تطوّرت إلى مستشفيات ومراكز للرعاية الاجتماعيّة. أُعلن طوباويًا سنة 2008، وما زال من أشهر الشخصيّات الدينيّة اللبنانيّة الحديثة."],"Joseph of Damascus":["Joseph of Damascus was an Antiochian Orthodox priest and teacher born in Beirut. He served the Christian community in Damascus and is remembered among those killed during the persecution of July 1860. His commemoration is especially important in the Orthodox Church of Antioch and forms part of the shared Christian memory of Lebanon and Syria. This profile identifies his Orthodox tradition clearly rather than presenting him as a Roman Catholic saint.","كان يوسف الدمشقي كاهنًا ومعلّمًا من كنيسة أنطاكية الأرثوذكسيّة، وُلد في بيروت. خدم الجماعة المسيحيّة في دمشق وتُكرّمه الكنيسة بين الذين قُتلوا خلال اضطهاد تموز 1860. ويحظى تذكاره بأهميّة خاصّة في كنيسة أنطاكية الأرثوذكسيّة، ويشكّل جزءًا من الذاكرة المسيحيّة المشتركة بين لبنان وسوريا. وتوضّح هذه البطاقة انتماءه الأرثوذكسي بدل تقديمه كقديس في الكنيسة الكاثوليكيّة الرومانيّة."]};
  for (const entry of entries) {
    const detail = detailedLebanese[entry.en];
    if (detail) { entry.storyEn = detail[0]; entry.storyAr = detail[1]; }
  }


  const detailedWorld = {"Francis of Assisi":["Born Giovanni di Pietro Bernardone in Assisi, Francis grew up in a wealthy merchant family and initially dreamed of a life of status and adventure. A period of illness and spiritual searching changed his priorities. He embraced poverty, repaired small churches and began preaching a life centred on the Gospel. Companions joined him, forming the beginnings of the Franciscan movement. Francis showed a special love for people on the margins and for creation, and his Canticle of the Creatures remains a beloved hymn of praise. He died in 1226 and was canonised in 1228.","وُلد فرنسيس باسم جوفاني برناردوني في أسيزي، ونشأ في عائلة تجاريّة غنيّة وكان يحلم أوّلًا بالمكانة والمغامرة. لكنّ المرض والبحث الروحي غيّرا أولويّاته. اختار الفقر، ورمّم كنائس صغيرة وبدأ يكرز بحياة تتمحور حول الإنجيل. انضمّ إليه رفاق وشكّلوا بدايات الحركة الفرنسيسكانيّة. أحبّ فرنسيس المهمّشين والخليقة، وما زالت نشيدته «تسبيح الخليقة» ترنيمة محبوبة. توفّي سنة 1226 وأُعلن قديسًا سنة 1228."],"Clare of Assisi":["Clare was born into a noble family in Assisi and was inspired by Francis’s preaching. In 1212 she left her family home to embrace a life of poverty and prayer. She founded the community that became the Poor Clares, shaping a form of Franciscan life for women. Clare defended her community’s commitment to simplicity and dependence on God, even when powerful people urged the sisters to accept wealth and security. Her life joined contemplative prayer with courage and leadership.","وُلدت كلارا في عائلة نبيلة في أسيزي وتأثّرت بكرازة فرنسيس. سنة 1212 تركت بيت عائلتها لتختار حياة الفقر والصلاة. وأسّست الجماعة التي أصبحت راهبات الكلاريس الفقيرات، وأسهمت في تشكيل الحياة الفرنسيسكانيّة للنساء. دافعت كلارا عن التزام جماعتها بالبساطة والاتّكال على الله، حتى عندما حاول أصحاب النفوذ إقناع الراهبات بقبول الثروة والأمان. جمعت حياتها بين الصلاة التأمليّة والشجاعة والقيادة."],"Augustine of Hippo":["Augustine was born in North Africa in 354 and spent his early adulthood searching through different philosophies and ways of life. His mother Monica prayed for him for many years. After encountering Christian teaching in Milan and hearing the preaching of Ambrose, Augustine was baptised by Ambrose in 387. He returned to North Africa, became a priest and then bishop of Hippo, and wrote works that shaped Christian thought, especially his Confessions and The City of God. He died in 430 while Hippo was under siege.","وُلد أوغسطينوس في شمال أفريقيا سنة 354، وأمضى شبابه يبحث في فلسفات وطرق حياة مختلفة. صلّت والدته مونيكا من أجله سنوات طويلة. وبعد تعرّفه إلى التعليم المسيحي في ميلانو وسماعه وعظ أمبروسيوس، عمّده أمبروسيوس سنة 387. عاد إلى شمال أفريقيا وأصبح كاهنًا ثم أسقف هيبّون، وكتب مؤلّفات أثّرت في الفكر المسيحي، ولا سيّما «اعترافاتي» و«مدينة الله». توفّي سنة 430 فيما كانت هيبّون تحت الحصار."],"Monica":["Monica was born in North Africa in the fourth century and became the mother of Augustine. Christian tradition remembers her as a woman of persistent prayer, patience and practical care for her family. She accompanied Augustine during important stages of his search for truth and lived to see his baptism in Milan. Their conversations and her example of faith became part of Augustine’s own account of his conversion. Monica is honoured as a patron of mothers and people who pray for family members.","وُلدت مونيكا في شمال أفريقيا في القرن الرابع، وكانت والدة أوغسطينوس. يذكرها التقليد المسيحي امرأة مثابرة في الصلاة وصبورة ومهتمّة بعائلتها. رافقت أوغسطينوس في مراحل مهمّة من بحثه عن الحقيقة، وعاشت لترى معموديّته في ميلانو. وأصبحت أحاديثهما ومثالها الإيماني جزءًا من رواية أوغسطينوس عن اهتدائه. وتُكرّم مونيكا شفيعة للأمّهات وللذين يصلّون من أجل أفراد عائلاتهم."],"Benedict of Nursia":["Benedict was born in central Italy and studied in Rome before withdrawing from public life to seek God in solitude. Other people joined him, and he eventually founded monasteries, including Monte Cassino. His Rule offered a balanced pattern of prayer, work, study and community life, guided by moderation and hospitality. Benedictine monasteries became centres of learning, agriculture and care for travellers through centuries of European history. He is remembered as a foundational figure of Western monasticism.","وُلد بندكتس في وسط إيطاليا ودرس في روما قبل أن يبتعد عن الحياة العامّة بحثًا عن الله في العزلة. انضمّ إليه آخرون، فأسّس أديرة منها دير مونتي كاسينو. وقدّمت قاعدته الرهبانيّة نظامًا متوازنًا يجمع الصلاة والعمل والدراسة والحياة الجماعيّة، مع الاعتدال والضيافة. وأصبحت الأديرة البندكتيّة مراكز للعلم والزراعة واستقبال المسافرين عبر قرون من التاريخ الأوروبي. ويُذكر كشخصيّة تأسيسيّة في الرهبنة الغربيّة."],"Anthony the Great":["Anthony was born in Egypt around 251. After hearing the Gospel call to leave possessions and follow Christ, he gave away his inheritance and began a life of prayer in the desert. Other seekers gathered around him, and his example helped shape Christian monasticism in Egypt. Athanasius later wrote a biography of Anthony that spread his reputation throughout the Christian world. Anthony is remembered not as someone who escaped responsibility, but as a person who sought inner freedom and spiritual discipline through prayer.","وُلد أنطونيوس الكبير في مصر نحو سنة 251. وبعد سماعه دعوة الإنجيل إلى ترك الممتلكات واتباع المسيح، وزّع ميراثه وبدأ حياة صلاة في الصحراء. اجتمع حوله طالبو الحياة الروحيّة، وأسهم مثاله في نشأة الرهبنة المسيحيّة في مصر. وكتب أثناسيوس لاحقًا سيرة أنطونيوس التي نشرت شهرته في العالم المسيحي. ويُذكر لا كشخص هرب من المسؤوليّة، بل كإنسان طلب الحريّة الداخليّة والانضباط الروحي بالصلاة."],"Athanasius of Alexandria":["Athanasius became Bishop of Alexandria in the fourth century and defended the Christian teaching that the Son is truly divine and not a created being. This debate shaped the Council of Nicaea and the Church’s language about the Trinity. His convictions brought repeated exile and conflict with political authorities, but he continued writing, teaching and caring for his community. His work On the Incarnation remains an important Christian text. He is honoured as a defender of Nicene faith and a Doctor of the Church.","أصبح أثناسيوس أسقف الإسكندريّة في القرن الرابع، ودافع عن التعليم المسيحي بأنّ الابن إله حقّ وليس مخلوقًا. شكّل هذا الجدل مجمع نيقية ولغة الكنيسة في شرح الثالوث. أدّت مواقفه إلى النفي والصراع المتكرّر مع السلطات السياسيّة، لكنه واصل الكتابة والتعليم ورعاية جماعته. وما زال كتابه «في التجسّد» نصًّا مسيحيًّا مهمًّا. وتكرّمه الكنيسة مدافعًا عن إيمان نيقية ومعلّمًا للكنيسة."],"Basil the Great":["Basil was born in Cappadocia into a family known for Christian faith and learning. After studying in Athens, he chose a life of prayer and helped organise monastic communities. As Bishop of Caesarea, he defended the Nicene faith and worked to support people who were poor, sick or without shelter. His charitable complex included care for travellers and the ill. Basil’s writings on the Holy Spirit, community life and Christian responsibility made him one of the great teachers of the early Church.","وُلد باسيليوس في كبادوكية في عائلة عُرفت بالإيمان المسيحي والعلم. وبعد دراسته في أثينا، اختار حياة الصلاة وساعد على تنظيم الجماعات الرهبانيّة. وبصفته أسقف قيصريّة، دافع عن إيمان نيقية وعمل لمساندة الفقراء والمرضى والمشرّدين. وشمل مشروعه الخيري رعاية المسافرين والمرضى. وجعلت كتاباته عن الروح القدس والحياة الجماعيّة والمسؤوليّة المسيحيّة منه أحد كبار معلّمي الكنيسة الأولى."],"Gregory Nazianzen":["Gregory was born in Cappadocia and became one of the most influential theologians of the fourth century. He studied in Athens with Basil, and the two shared a deep friendship and commitment to Christian learning. Gregory later served as Bishop of Constantinople during the debates over the Trinity. His sermons and theological poems helped explain the Church’s belief in the Father, Son and Holy Spirit. He is remembered for the depth of his teaching and the beauty of his spiritual writing.","وُلد غريغوريوس النزينزي في كبادوكية وأصبح من أكثر لاهوتيي القرن الرابع تأثيرًا. درس في أثينا مع باسيليوس، وجمعتهما صداقة عميقة والتزام بالعلم المسيحي. خدم لاحقًا أسقفًا للقسطنطينيّة خلال النقاشات حول الثالوث. ساعدت عظاته وقصائده اللاهوتيّة على شرح إيمان الكنيسة بالآب والابن والروح القدس. ويُذكر بعمق تعليمه وجمال كتاباته الروحيّة."],"John Chrysostom":["John was born in Antioch and became famous for his clear preaching, which earned him the name Chrysostom, meaning “Golden-Mouthed.” He served as a priest in Antioch and later as Archbishop of Constantinople. His sermons explained Scripture and challenged greed, injustice and the neglect of the poor. His criticism of powerful figures led to exile, and he died while travelling under guard in 407. His homilies and liturgical tradition continue to influence Eastern Christianity.","وُلد يوحنّا في أنطاكية واشتهر بوعظه الواضح، حتى لُقّب «ذهبيّ الفم». خدم كاهنًا في أنطاكية ثم أصبح رئيس أساقفة القسطنطينيّة. شرحت عظاته الكتاب المقدّس وانتقدت الطمع والظلم وإهمال الفقراء. أدّى نقده لأصحاب النفوذ إلى نفيه، وتوفّي سنة 407 خلال نقله تحت الحراسة. وما زالت عظاته والتقليد الليتورجي المرتبط به يؤثّران في المسيحيّة الشرقيّة."],"Nicholas of Myra":["Nicholas served as Bishop of Myra in Lycia, in what is now Türkiye. Details of his life are mixed with later traditions, but he became widely remembered for generosity and concern for people in need. Stories tell of him helping a family in secret and protecting people facing injustice. His reputation for gift-giving helped shape the later figure of Santa Claus, though the historical bishop and the modern holiday character are not the same. He remains one of the most widely venerated saints in Eastern and Western Christianity.","خدم نيقولاوس أسقفًا لميرا في ليكيا، في منطقة تركيا اليوم. اختلطت تفاصيل حياته بتقاليد لاحقة، لكنه اشتهر بالكرم والاهتمام بالمحتاجين. وتروي القصص أنّه ساعد عائلة سرًّا ودافع عن أشخاص تعرّضوا للظلم. وأسهمت سمعته في العطاء في تشكيل الصورة اللاحقة لشخصيّة بابا نويل، مع أنّ الأسقف التاريخي وشخصيّة العيد الحديثة ليسا الشخص نفسه. وما زال من أكثر القديسين إكرامًا في المسيحيّة الشرقيّة والغربيّة."],"George":["George is one of the most widely honoured Christian martyrs, especially in the Middle East, the Mediterranean and Europe. Later tradition presents him as a Roman soldier who refused to abandon his Christian faith during persecution. The story of George and the dragon is a medieval symbol of courage overcoming evil, not a literal historical biography. Churches and towns across Lebanon and the world bear his name, and his feast is celebrated on 23 April in many traditions."],"Patrick of Ireland":["Patrick was born in Roman Britain and was taken to Ireland as a young captive. After escaping and returning home, he later chose to go back to Ireland as a missionary. His letters describe hardship, prayer and his sense of calling to serve the people among whom he had once been held. Patrick became associated with the growth of Christianity in Ireland, though many popular legends about him developed centuries later. He is honoured as Ireland’s principal patron saint.","وُلد باتريك في بريطانيا الرومانيّة وأُخذ إلى أيرلندا أسيرًا وهو شاب. وبعد هروبه وعودته إلى بلاده، اختار لاحقًا الرجوع إلى أيرلندا مرسلًا. تصف رسائله الصعوبات والصلاة وشعوره بالدعوة إلى خدمة الشعب الذي عاش بينه أسيرًا. ارتبط باتريك بانتشار المسيحيّة في أيرلندا، رغم أنّ أساطير شعبيّة كثيرة عنه ظهرت بعد قرون. وتكرّمه الكنيسة شفيعًا رئيسيًّا لأيرلندا."],"Francis Xavier":["Francis Xavier was born in Navarre and studied at the University of Paris, where he met Ignatius of Loyola and became one of the first Jesuits. He travelled as a missionary to India, Southeast Asia and Japan, learning languages and adapting his teaching to local communities. His letters describe long journeys, difficult conditions and a desire to make Christian teaching accessible. He died in 1552 while preparing to enter China. He is remembered as one of the great missionaries of the early modern Church.","وُلد فرنسيس كسفاريوس في نافارا ودرس في جامعة باريس، حيث التقى إغناطيوس دي لويولا وأصبح من أوائل اليسوعيّين. سافر مرسلًا إلى الهند وجنوب شرق آسيا واليابان، وتعلّم اللغات وكيّف تعليمه مع الجماعات المحليّة. تصف رسائله الرحلات الطويلة والظروف الصعبة ورغبته في جعل التعليم المسيحي مفهومًا للناس. توفّي سنة 1552 بينما كان يستعدّ لدخول الصين. ويُذكر كأحد كبار مرسلي الكنيسة في العصر الحديث المبكر."],"Ignatius of Loyola":["Ignatius was a Basque soldier whose life changed after he was seriously wounded in battle. During recovery he read books about Jesus and the saints and began a long process of spiritual conversion. He later studied, gathered companions in Paris and helped found the Society of Jesus, known as the Jesuits. His Spiritual Exercises became an influential guide to prayer, discernment and making life decisions. Ignatius led the new order from Rome and emphasised education, mission and service to the Church.","كان إغناطيوس جنديًّا من إقليم الباسك، وتغيّرت حياته بعد إصابته إصابة خطيرة في المعركة. خلال فترة التعافي قرأ كتبًا عن يسوع والقديسين وبدأ مسيرة اهتداء روحي طويلة. درس لاحقًا وجمع رفاقًا في باريس وساعد على تأسيس جمعيّة يسوع المعروفة باليسوعيّين. أصبحت «الرياضات الروحيّة» التي وضعها دليلًا مؤثّرًا للصلاة والتمييز واتّخاذ القرارات. قاد إغناطيوس الرهبنة الجديدة من روما وشدّد على التعليم والرسالة وخدمة الكنيسة."],"Teresa of Ávila":["Teresa was born in Ávila, Spain, and entered the Carmelite convent as a young woman. Her experience of prayer led her to seek a deeper and more disciplined contemplative life. She worked to reform Carmelite communities, founding convents that returned to simplicity, prayer and community. Her books, including The Interior Castle and The Way of Perfection, describe the journey of prayer with remarkable insight. She is honoured as a Doctor of the Church and one of the great teachers of Christian spirituality.","وُلدت تريزا في أفيلا بإسبانيا ودخلت دير الكرمليّات شابّة. قادتها خبرة الصلاة إلى طلب حياة تأمليّة أعمق وأكثر انضباطًا. عملت على إصلاح الجماعات الكرمليّة وأسّست أديرة عادت إلى البساطة والصلاة والحياة المشتركة. تصف كتبها، ومنها «القصر الداخلي» و«طريق الكمال»، مسيرة الصلاة ببصيرة روحيّة لافتة. وتكرّمها الكنيسة معلّمة للكنيسة وإحدى أبرز معلّمات الروحانيّة المسيحيّة."],"John of the Cross":["John of the Cross was a Spanish Carmelite priest who worked with Teresa of Ávila in the reform of the Carmelite Order. His commitment to the reform brought opposition and imprisonment, during which he continued to pray and write poetry. His works The Dark Night of the Soul and The Spiritual Canticle explore faith, love and the transformation of the soul. He is remembered as a major Christian poet and mystic, and as a Doctor of the Church.","كان يوحنّا الصليب كاهنًا كرملّيًا إسبانيًّا عمل مع تريزا الأفيليّة في إصلاح الرهبنة الكرمليّة. أثار التزامه بالإصلاح معارضة أدّت إلى سجنه، حيث واصل الصلاة وكتابة الشعر. تستكشف مؤلّفاته «الليل المظلم» و«النشيد الروحي» الإيمان والمحبّة وتحوّل النفس. ويُذكر شاعرًا وصوفيًّا مسيحيًّا كبيرًا ومعلّمًا للكنيسة."],"Thérèse of Lisieux":["Thérèse was born in Alençon, France, and entered the Carmelite convent at Lisieux while still very young. She lived a hidden life of prayer, community duties and small acts of kindness. In her autobiography, Story of a Soul, she described her “little way”: trusting God and expressing love through ordinary actions rather than seeking greatness. She died at twenty-four, and her writings later reached readers around the world. She was declared a Doctor of the Church in 1997.","وُلدت تريز في ألانسون بفرنسا ودخلت دير الكرمليّات في ليزيو وهي صغيرة. عاشت حياة خفيّة من الصلاة وخدمة الجماعة وأعمال المحبّة الصغيرة. وفي سيرتها «قصة نفس» شرحت «الطريق الصغيرة»: الاتّكال على الله والتعبير عن المحبّة بالأعمال العاديّة بدل السعي إلى العظمة. توفّيت في الرابعة والعشرين، ثم وصلت كتاباتها إلى قرّاء في أنحاء العالم. أُعلنت معلّمة للكنيسة سنة 1997."],"John Bosco":["John Bosco grew up in a poor farming family in northern Italy and became a priest devoted to young people, especially those who had little support or access to education. In Turin he opened places where boys could study, learn a trade, pray and find a stable community. He founded the Salesians and, with Mary Mazzarello, helped establish the Daughters of Mary Help of Christians. His educational approach emphasised reason, religion and loving kindness. He is remembered as a patron of youth and Catholic education.","نشأ يوحنّا بوسكو في عائلة زراعيّة فقيرة في شمال إيطاليا، وأصبح كاهنًا كرّس حياته للشباب، ولا سيّما الذين افتقروا إلى الدعم وفرص التعليم. في تورينو افتتح مراكز يستطيع فيها الفتيان الدراسة وتعلّم مهنة والصلاة والانتماء إلى جماعة ثابتة. أسّس رهبنة الساليزيان، وساعد مع ماريّا ماتزيلّو على تأسيس بنات مريم معونة المسيحيّين. ركّز أسلوبه التربوي على العقل والدين والمحبّة. ويُذكر شفيعًا للشباب والتعليم الكاثوليكي."],"Vincent de Paul":["Vincent was born in rural France and became a priest who devoted himself to people living in poverty. Encounters with families, prisoners and people displaced by war shaped his conviction that charity must be organised and practical. He founded the Congregation of the Mission and worked with Louise de Marillac to establish the Daughters of Charity. Vincent encouraged communities to provide food, shelter, education and care rather than relying only on occasional acts of generosity. His legacy continues through charitable organisations around the world.","وُلد فنسان دي بول في ريف فرنسا وأصبح كاهنًا كرّس حياته للفقراء. شكّلت لقاءاته بالعائلات والسجناء والمهجّرين بسبب الحروب قناعته بأنّ المحبّة يجب أن تكون منظّمة وعمليّة. أسّس جمعيّة الرسالة وعمل مع لويز دو ماريّاك على تأسيس بنات المحبّة. شجّع الجماعات على تأمين الطعام والمأوى والتعليم والرعاية بدل الاكتفاء بالمساعدات المتقطّعة. وما زال إرثه حاضرًا في مؤسّسات خيريّة حول العالم."],"Martin de Porres":["Martin was born in Lima, Peru, to a Spanish father and an Afro-Peruvian mother. Facing social barriers because of his mixed heritage, he entered the Dominican community and served in humble roles before becoming a religious brother. He cared for the sick, welcomed people who were poor and helped organise medical care. His life challenged prejudice through practical compassion and a deep commitment to prayer. He became the first Black saint of the Americas to be canonised and is honoured as a patron of social justice and interracial harmony.","وُلد مارتن في ليما في بيرو لأب إسباني وأم من أصل أفريقي بيروفي. واجه عوائق اجتماعيّة بسبب أصوله المختلطة، وانضمّ إلى الجماعة الدومينيكيّة وخدم في أعمال متواضعة قبل أن يصبح أخًا راهبًا. اعتنى بالمرضى واستقبل الفقراء وساعد على تنظيم الرعاية الطبيّة. واجهت حياته التحيّز من خلال الرحمة العمليّة والالتزام العميق بالصلاة. أصبح أوّل قديس من ذوي الأصول الأفريقيّة في الأميركتين يُعلن قديسًا، ويُكرّم شفيعًا للعدالة الاجتماعيّة والوئام بين الأعراق."],"Rose of Lima":["Rose was born in Lima, Peru, and became known for a life of prayer, service and care for people who were sick and poor. She joined the Dominican Third Order and lived a simple life while helping her family and serving neighbours. She created a small room in her home where she could pray and welcome those in need. Her reputation for holiness spread beyond Lima, and she became the first person born in the Americas to be canonised. She is honoured as a patron saint of Latin America and the Philippines.","وُلدت روزا في ليما في بيرو، وعُرفت بحياة الصلاة والخدمة والاهتمام بالمرضى والفقراء. انضمّت إلى الرهبنة الدومينيكيّة الثالثة وعاشت ببساطة، مع مساعدة عائلتها وخدمة جيرانها. خصّصت غرفة صغيرة في بيتها للصلاة واستقبال المحتاجين. انتشرت سمعتها في القداسة خارج ليما، وأصبحت أوّل شخص مولود في الأميركتين يُعلن قديسًا. وتُكرّم شفيعة لأميركا اللاتينيّة والفيليبين."],"Kateri Tekakwitha":["Kateri was born in the Mohawk community in what is now New York State in the seventeenth century. After surviving illness in childhood, she learned about Christianity from missionaries and was baptised as a young woman. Her decision brought tension with some members of her community, and she eventually moved to a Christian settlement near Montreal. She lived a life of prayer, care for others and respect for her Indigenous heritage. Canonised in 2012, she is the first Indigenous person from North America to be declared a saint by the Catholic Church.","وُلدت كاتيري في جماعة الموهوك في المنطقة التي أصبحت اليوم ولاية نيويورك في القرن السابع عشر. وبعد نجاتها من مرض في طفولتها، تعرّفت إلى المسيحيّة على يد مرسلين واعتمدت شابّة. سبّب قرارها توتّرًا مع بعض أفراد جماعتها، فانتقلت في النهاية إلى مستوطنة مسيحيّة قرب مونتريال. عاشت حياة صلاة واهتمام بالآخرين واحترام لتراثها الأصلي. أُعلنت قديسة سنة 2012، وهي أوّل شخص من سكّان أميركا الأصليّين في الشمال تعلنه الكنيسة الكاثوليكيّة قديسًا."],"Josephine Bakhita":["Josephine Bakhita was born in the Darfur region of Sudan and was taken from her family as a child, enduring enslavement before eventually reaching Italy. There she encountered the Canossian Sisters, received Christian formation and was baptised. She later became a Canossian religious sister, serving through ordinary work, hospitality and encouragement. Her life became a witness to human dignity, freedom and forgiveness. She was canonised in 2000 and is honoured as a patron of people affected by trafficking and exploitation.","وُلدت جوزفين بخيتا في منطقة دارفور في السودان، وفُصلت عن عائلتها وهي طفلة وعانت الاستعباد قبل أن تصل في النهاية إلى إيطاليا. هناك تعرّفت إلى راهبات كانوسّا وتلقّت التنشئة المسيحيّة واعتمدت. أصبحت لاحقًا راهبة كانوسيّة وخدمت بالأعمال اليوميّة والضيافة والتشجيع. صارت حياتها شهادة لكرامة الإنسان والحريّة والمغفرة. أُعلنت قديسة سنة 2000 وتُكرّم شفيعة للمتضرّرين من الاتجار بالبشر والاستغلال."],"Maximilian Kolbe":["Maximilian Kolbe was a Polish Franciscan priest who founded a publishing apostolate devoted to the Virgin Mary and used modern media to share Christian teaching. During the Second World War he was arrested by the Nazi authorities and sent to Auschwitz. There he offered to take the place of another prisoner who had been selected for death. He was killed in 1941. Pope John Paul II canonised him in 1982 and described him as a martyr of charity. His story is remembered as an extraordinary act of self-giving love.","كان مكسيميليان كولبي كاهنًا فرنسيسكانيًّا بولنديًّا أسّس عملًا إعلاميًّا رسوليًّا مكرّسًا للعذراء مريم واستخدم وسائل الإعلام الحديثة لنشر التعليم المسيحي. خلال الحرب العالميّة الثانية اعتقلته السلطات النازيّة وأرسلته إلى أوشفيتز. هناك عرض أن يحلّ مكان سجين آخر حُكم عليه بالموت. قُتل سنة 1941. أعلنه البابا يوحنا بولس الثاني قديسًا سنة 1982 ووصفه شهيد المحبّة. وتُذكر قصّته كعمل استثنائي من بذل الذات."],"Oscar Romero":["Oscar Romero became Archbishop of San Salvador in 1977 during a period of political violence and deep social division. After the killing of his friend and fellow priest Rutilio Grande, Romero increasingly spoke publicly against violence, injustice and the abuse of the poor. His radio homilies reached people across the country and called for respect for human dignity. He was assassinated while celebrating Mass in 1980. Canonised in 2018, he is remembered as a pastor who stood with people who were vulnerable and unheard.","أصبح أوسكار روميرو رئيس أساقفة سان سلفادور سنة 1977 خلال مرحلة عنف سياسي وانقسام اجتماعي عميق. وبعد مقتل صديقه والكاهن روتيليو غراندي، صار يتكلّم علنًا بصورة أكبر ضد العنف والظلم واستغلال الفقراء. وصلت عظاته الإذاعيّة إلى الناس في أنحاء البلاد ودعت إلى احترام كرامة الإنسان. اغتيل بينما كان يحتفل بالقداس سنة 1980. أُعلن قديسًا سنة 2018، ويُذكر راعيًا وقف إلى جانب الضعفاء ومن لا صوت لهم."],"Mother Teresa of Calcutta":["Born Anjezë Gonxhe Bojaxhiu in Skopje, Teresa joined the Sisters of Loreto and travelled to India to teach. In 1946 she experienced what she described as a call to serve the poorest of the poor, and she began working in the streets of Kolkata. She founded the Missionaries of Charity, whose members serve people who are sick, abandoned and in extreme poverty. Her work spread internationally, while also attracting debate about aspects of her institutions and methods. She was canonised in 2016 and remains one of the most recognisable Catholic figures of the modern era.","وُلدت أنييس غونكشا بوجاكسيو في سكوبيه، وانضمّت إلى راهبات لوريتو وسافرت إلى الهند للتعليم. سنة 1946 اختبرت ما وصفته بدعوة لخدمة أفقر الفقراء، فبدأت العمل في شوارع كالكوتا. أسّست جمعيّة مرسلات المحبّة، التي يخدم أعضاؤها المرضى والمتروكين والذين يعيشون في فقر شديد. انتشر عملها عالميًّا، وأثار أيضًا نقاشات حول بعض جوانب مؤسّساتها وأساليبها. أُعلنت قديسة سنة 2016 وما زالت من أكثر الشخصيّات الكاثوليكيّة المعروفة في العصر الحديث."],"John Paul II":["Karol Wojtyła was born in Poland and experienced the loss of close family members while growing up. During the Nazi occupation he studied secretly and worked in a quarry before entering the seminary. He became Archbishop of Kraków and was elected Pope in 1978, the first non-Italian pope in more than four centuries. His long pontificate included major journeys, interfaith encounters and a prominent role in the history of the late twentieth century. He encouraged young people, promoted human dignity and helped inspire the World Youth Day gatherings. He was canonised in 2014.","وُلد كارول فويتيوا في بولندا واختبر فقدان أفراد مقرّبين من عائلته خلال نشأته. أثناء الاحتلال النازي درس سرًّا وعمل في مقلع للحجارة قبل دخوله الإكليريكيّة. أصبح رئيس أساقفة كراكوف وانتُخب بابا سنة 1978، وكان أوّل بابا غير إيطالي منذ أكثر من أربعة قرون. شملت حبريّته الطويلة رحلات كبرى ولقاءات بين الأديان ودورًا بارزًا في تاريخ أواخر القرن العشرين. شجّع الشباب ودافع عن كرامة الإنسان وأسهم في إطلاق لقاءات الشبيبة العالميّة. أُعلن قديسًا سنة 2014."],"Carlo Acutis":["Carlo Acutis was born in London in 1991 and grew up in Italy. As a teenager he loved computers, created a website documenting Eucharistic miracles and used his technical skills to share his faith. He attended school, enjoyed ordinary friendships and was known for helping people who were poor or isolated. He died of leukaemia in 2006 at the age of fifteen. His life has become an example of how faith, technology, friendship and generosity can belong together. He was canonised in 2025.","وُلد كارلو أكوتيس في لندن سنة 1991 ونشأ في إيطاليا. أحبّ الحاسوب في مراهقته، وأنشأ موقعًا يوثّق المعجزات الإفخارستيّة واستخدم مهاراته التقنيّة لمشاركة إيمانه. كان يذهب إلى المدرسة ويعيش صداقاته العاديّة، وعُرف بمساعدة الفقراء والمعزولين. توفّي بمرض سرطان الدم سنة 2006 عن خمسة عشر عامًا. أصبحت حياته مثالًا على إمكانيّة اجتماع الإيمان والتكنولوجيا والصداقة والكرم. أُعلن قديسًا سنة 2025."],"Pier Giorgio Frassati":["Pier Giorgio was born in Turin in 1901 into a prominent family, but he devoted much of his time to friendship, prayer and service among people who were poor. He joined Catholic youth groups, enjoyed mountain climbing and saw faith as something to be lived through concrete acts of charity. He quietly helped families with money, food and practical support, often without telling his own family. He died at twenty-four from polio, and his funeral drew many people who had benefited from his kindness. He was canonised in 2025.","وُلد بيير جورجيو فراساتي في تورينو سنة 1901 في عائلة معروفة، لكنه كرّس جزءًا كبيرًا من وقته للصداقة والصلاة وخدمة الفقراء. انضمّ إلى مجموعات شبابيّة كاثوليكيّة وأحبّ تسلّق الجبال، ورأى أنّ الإيمان يُعاش بأعمال محبّة ملموسة. ساعد عائلات بهدوء بالمال والطعام والدعم العملي، وغالبًا من دون إخبار عائلته. توفّي في الرابعة والعشرين بمرض شلل الأطفال، وشارك في جنازته كثيرون ممّن اختبروا لطفه. أُعلن قديسًا سنة 2025."],"Elizabeth of Hungary":["Elizabeth was born into a royal family in the early thirteenth century and became Landgravine of Thuringia through marriage. She used her position and resources to care for people who were poor and sick, establishing a hospital and personally serving those in need. After her husband’s death she embraced a life of simplicity and charitable work. Her example inspired hospitals, religious communities and charitable organisations across Europe. She is remembered as a patron of charity workers and people who serve the poor."],"Catherine of Siena":["Catherine was born in Siena in 1347 and became a Dominican tertiary devoted to prayer and service. Though she had no formal political office, she wrote letters to popes, rulers and civic leaders, urging peace, reform and responsibility. She travelled to Avignon to encourage the pope to return to Rome and helped mediate conflicts in Italy. Her Dialogue records her spiritual reflections and deep love of God. She was declared a Doctor of the Church in 1970 and is one of the patron saints of Europe."],"Lucy of Syracuse":["Lucy was a young Christian woman from Syracuse in Sicily, remembered as a martyr during the persecution under Diocletian. Her name became associated with light, and her feast on 13 December is celebrated especially in Scandinavia and parts of Europe. The historical details of her life are preserved through early Christian traditions, and she is honoured as a patron of people seeking hope and spiritual clarity."],"Agnes of Rome":["Agnes is remembered as a young Christian martyr in Rome during the early persecutions. Ancient accounts describe her as choosing fidelity to Christ despite pressure to abandon her faith. Her tomb on the Via Nomentana became an early place of Christian devotion, and a basilica was later built in her honour. She is especially remembered as a patron of young people and a symbol of courage and integrity."],"Cecilia":["Cecilia is honoured as an early Christian martyr in Rome and is especially associated with music and musicians. Later accounts describe her as a woman who remained faithful to Christ and encouraged others in the Christian community. Her name appears in the Roman Canon of the Mass, showing the ancient importance of her cult. The historical details of her life are limited, but her witness has inspired centuries of sacred music and devotion."],"John XXIII":["Angelo Giuseppe Roncalli was born to a farming family in northern Italy and became a priest, diplomat and bishop. After serving as papal representative in several countries, he was elected Pope John XXIII in 1958. He convened the Second Vatican Council, inviting the Church to renew its life and engage the modern world through dialogue and pastoral openness. His warmth and simplicity earned him affection far beyond the Catholic Church. He was canonised in 2014."],"Paul VI":["Giovanni Battista Montini became Pope Paul VI in 1963 and guided the Second Vatican Council through its final sessions and implementation. He worked to renew Catholic worship and pastoral life while seeking dialogue with other Christians, other religions and the modern world. His travels included historic visits outside Italy, and he was the first pope to address the United Nations. He is remembered for guiding a period of major change with a commitment to unity and peace. He was canonised in 2018."]};
  for (const entry of entries) {
    const detail = detailedWorld[entry.en];
    if (detail) { entry.storyEn = detail[0]; if (detail[1]) entry.storyAr = detail[1]; }
  }

  const additionalArabicStories = {"Elizabeth of Hungary":"وُلدت إليصابات في عائلة ملكيّة في مطلع القرن الثالث عشر، وأصبحت أميرة تورينغن بزواجها. استخدمت مكانتها ومواردها لخدمة الفقراء والمرضى، وأسّست مستشفى وكانت تخدم المحتاجين بنفسها. وبعد وفاة زوجها اختارت حياة بسيطة وأعمال رحمة. ألهم مثالها مستشفيات وجماعات رهبانيّة ومؤسّسات خيريّة في أنحاء أوروبا. وتُكرّم شفيعة للعاملين في أعمال الرحمة وخدمة الفقراء.","Catherine of Siena":"وُلدت كاترينا في سيينا سنة 1347، وأصبحت من العلمانيّات الدومينيكيّات المكرّسات للصلاة والخدمة. ورغم أنّها لم تشغل منصبًا سياسيًّا، كتبت إلى الباباوات والحكّام وقادة المدن داعيةً إلى السلام والإصلاح وتحمل المسؤوليّة. سافرت إلى أفينيون لتشجّع البابا على العودة إلى روما، وساعدت في الوساطة في نزاعات إيطاليا. ويسجّل كتابها «الحوار» تأمّلاتها الروحيّة ومحبّتها العميقة لله. أُعلنت معلّمة للكنيسة سنة 1970 وهي من شفيعات أوروبا.","Lucy of Syracuse":"تُذكر لوسي كشابّة مسيحيّة من سيراكوزا في صقلية، استُشهدت خلال الاضطهادات الأولى. ارتبط اسمها بالنور، ويُحتفل بعيدها في 13 كانون الأوّل، ولا سيّما في الدول الاسكندنافيّة وأجزاء من أوروبا. حُفظت تفاصيل حياتها في تقاليد مسيحيّة قديمة، وتُكرّم شفيعة للرجاء والبصيرة الروحيّة.","Agnes of Rome":"تُذكر أغنيس كشابّة شهيدة مسيحيّة في روما خلال الاضطهادات الأولى. وتصف الروايات القديمة ثباتها في الإيمان بالمسيح رغم الضغوط للتخلّي عنه. أصبح ضريحها على طريق نومنتانا مكانًا مبكرًا لإكرام المسيحيّين، ثم بُنيت كنيسة على اسمها. وتُكرّم بصورة خاصّة شفيعة للشباب ورمزًا للشجاعة والنزاهة.","Cecilia":"تُكرّم شيشيليا كشهيدة مسيحيّة مبكّرة في روما، وترتبط خصوصًا بالموسيقى والموسيقيّين. وتصف الروايات اللاحقة امرأة بقيت أمينة للمسيح وشجّعت آخرين في الجماعة المسيحيّة. يَرِد اسمها في القانون الروماني للقداس، ما يدلّ على قدم إكرامها. ورغم محدوديّة التفاصيل التاريخيّة عن حياتها، ألهمت سيرتها قرونًا من الموسيقى المقدّسة والتعبّد.","John XXIII":"وُلد أنجيلو جوزيبي رونكالي في عائلة زراعيّة في شمال إيطاليا، وأصبح كاهنًا ودبلوماسيًّا وأسقفًا. بعد خدمته ممثّلًا بابويًّا في دول عدّة، انتُخب البابا يوحنّا الثالث والعشرون سنة 1958. دعا إلى المجمع الفاتيكاني الثاني، مشجّعًا الكنيسة على تجديد حياتها والانفتاح على العالم الحديث بالحوار والرعاية. أكسبه دفؤه وبساطته محبّة تتجاوز حدود الكنيسة الكاثوليكيّة. أُعلن قديسًا سنة 2014.","Paul VI":"أصبح جوفاني باتيستا مونتيني البابا بولس السادس سنة 1963، وقاد المجمع الفاتيكاني الثاني خلال جلساته الأخيرة ومرحلة تطبيق قراراته. عمل على تجديد العبادة والحياة الرعويّة الكاثوليكيّة، وسعى إلى الحوار مع المسيحيّين الآخرين والأديان والعالم الحديث. شملت رحلاته زيارات تاريخيّة خارج إيطاليا، وكان أوّل بابا يخاطب الأمم المتّحدة. ويُذكر لقيادته مرحلة تغيير كبيرة مع التزامه بالوحدة والسلام. أُعلن قديسًا سنة 2018."};
  additionalArabicStories["George"] = "يُعدّ القديس جرجس من أكثر الشهداء المسيحيّين إكرامًا، ولا سيّما في الشرق الأوسط وحوض المتوسّط وأوروبا. وتقدّمه الرواية اللاحقة جنديًّا رومانيًّا رفض التخلّي عن إيمانه المسيحي خلال الاضطهاد. أمّا قصّة جرجس والتنين فهي رمز من العصور الوسطى لانتصار الشجاعة على الشر، وليست سيرة تاريخيّة حرفيّة. تحمل كنائس وبلدات كثيرة في لبنان والعالم اسمه، ويُحتفل بعيده في 23 نيسان في تقاليد عديدة.";
  for (const entry of entries) {
    if (additionalArabicStories[entry.en]) entry.storyAr = additionalArabicStories[entry.en];
  }
  // Keep the Lebanese collection focused on saints and blesseds with a clear Lebanese connection,
  // while retaining the widely recognised saints from the universal Church.
  entries.push({
    en: "Rita of Cascia", ar: "القديسة ريتا من كاشيا", letter: "R",
    imageUrl: "https://stritaparishnchiru.com/images/rita-thorn.jpeg",
    imagePage: "https://stritaparishnchiru.com/st-rita-history.html",
    status: "Saint · Augustinian nun · Patron of difficult causes",
    place: "Cascia, Italy", years: "c. 1381–1457",
    storyEn: "Rita was born in the town of Roccaporena near Cascia in central Italy. As a young woman she married and became a mother. After a difficult family life and the deaths of her husband and sons, she sought admission to the Augustinian convent in Cascia. There she lived for many years in prayer, humility, reconciliation and care for others. Her devotion to the Passion of Christ and her patient response to suffering became central to the way Catholics remember her. She died in 1457 and was canonised by Pope Leo XIII in 1900. Popular devotion often invokes her in difficult or seemingly impossible situations, but her life is also a witness to forgiveness, perseverance and hope.",
    storyAr: "وُلدت ريتا في بلدة روكّابورينا قرب كاشيا في وسط إيطاليا. تزوّجت في شبابها وأصبحت أمًّا، وعاشت ظروفًا عائليّة صعبة. وبعد وفاة زوجها وابنيها، طلبت الانضمام إلى دير الراهبات الأوغسطينيّات في كاشيا. عاشت هناك سنوات طويلة في الصلاة والتواضع والمصالحة وخدمة الآخرين. وتميّزت بتعبّدها لآلام المسيح وبسعيها إلى الغفران والرجاء. توفّيت سنة 1457 وأعلنها البابا لاون الثالث عشر قدّيسة سنة 1900. ويلجأ إليها كثيرون في القضايا الصعبة، لكن حياتها تذكّر أيضًا بأهميّة المصالحة والصبر والثقة بالله."
  });
  const lebaneseProfiles = new Set([
    "Aquilina of Byblos", "Barbara", "Charbel Makhlouf", "Estephan El Douaihy",
    "Ignatius Maloyan", "Nimatullah Al-Hardini", "Rafqa Pietra Choboq Ar-Rayès",
    "Estephan Nehme", "Leonard Melki", "Thomas Saleh", "The Massabki Brothers",
    "Maron", "John Maron", "Elias Hoayek", "Antonios Tarabay", "Blessed Jacques Haddad (Abouna Yaacoub)",
    "Joseph of Damascus"
  ]);
  const recognisedWorldSaints = new Set([
    "Joseph of Nazareth", "Francis of Assisi", "Clare of Assisi", "Augustine of Hippo",
    "Monica", "Benedict of Nursia", "Anthony the Great", "Nicholas of Myra", "George",
    "Patrick of Ireland", "Francis Xavier", "Ignatius of Loyola", "Teresa of Ávila",
    "John of the Cross", "Thérèse of Lisieux", "John Bosco", "Vincent de Paul",
    "Martin de Porres", "Rose of Lima", "Kateri Tekakwitha", "Josephine Bakhita",
    "Maximilian Kolbe", "Oscar Romero", "Mother Teresa of Calcutta", "John Paul II",
    "Carlo Acutis", "Pier Giorgio Frassati", "Elizabeth of Hungary", "Catherine of Siena",
    "Lucy of Syracuse", "Agnes of Rome", "Cecilia", "John XXIII", "Paul VI"
  ]);
  for (let i = entries.length - 1; i >= 0; i--) {
    const entry = entries[i];
    if (!lebaneseProfiles.has(entry.en) && !recognisedWorldSaints.has(entry.en) && entry.en !== "Rita of Cascia") {
      entries.splice(i, 1);
    } else {
      entry.group = lebaneseProfiles.has(entry.en) ? "Lebanese" : "Worldwide";
    }
  }
  entries.sort((a, b) => (a.group === b.group ? a.en.localeCompare(b.en) : a.group === "Lebanese" ? -1 : 1));
  const esc = (s) => String(s||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));

  async function loadSaintImages(list) {
    const pending = list.filter(s => !s.imageRequested && !s.imageUrl && !s.imageDisabled);
    pending.forEach(s => { s.imageRequested = true; });
    for (let i = 0; i < pending.length; i += 6) {
      await Promise.all(pending.slice(i, i + 6).map(async s => {
        const titles = [s.en, "Saint " + s.en];
        for (const title of titles) {
          try {
            const response = await fetch("https://en.wikipedia.org/api/rest_v1/page/summary/" + encodeURIComponent(title));
            if (!response.ok) continue;
            const page = await response.json();
            const image = page.thumbnail?.source || page.original?.source;
            if (image) {
              s.imageUrl = image;
              s.imagePage = page.content_urls?.desktop?.page || ("https://en.wikipedia.org/wiki/" + encodeURIComponent(page.title || title).replace(/%20/g, "_"));
              break;
            }
          } catch {}
        }
        const index = entries.indexOf(s);
        document.querySelectorAll('[data-saint-image="' + index + '"]').forEach(img => {
          if (s.imageUrl) {
            img.src = s.imageUrl;
            img.hidden = false;
            const placeholder = img.parentElement.querySelector(".saint-image-placeholder");
            if (placeholder) placeholder.hidden = true;
          }
        });
        document.querySelectorAll('[data-saint-image-credit="' + index + '"]').forEach(link => {
          if (s.imageUrl && s.imagePage) {
            link.href = s.imagePage;
            link.hidden = false;
          }
        });
      }));
    }
  }
  function saintPortrait(s, className = "saint-card-image") {
    const index = entries.indexOf(s);
    return '<div class="saint-portrait-wrap"><img class="' + className + '" data-saint-image="' + index + '" alt="Portrait of ' + esc(s.en) + '" src="' + (s.imageUrl ? esc(s.imageUrl) : "") + '"' + (s.imageUrl ? "" : " hidden") + '><span class="saint-image-placeholder"' + (s.imageUrl ? " hidden" : "") + '>' + esc(s.en.charAt(0)) + '</span></div>';
  }
  function openSaint(s){
    panelTitle.textContent=s.en;
    output.innerHTML=`<div class="saint-detail"><button class="back-button" data-saints-back>← Back to all saints / العودة إلى اللائحة</button><div class="saint-detail-heading">${saintPortrait(s, "saint-detail-image")}<div><p class="saint-status">${esc(s.status)} · ${esc(s.years)}</p><h3>${esc(s.en)}</h3><p class="meaning">${esc(s.place)}</p><a class="saint-image-credit" data-saint-image-credit="${entries.indexOf(s)}" href="${s.imagePage || "#"}" target="_blank" rel="noopener"${s.imageUrl ? "" : " hidden"}>Portrait source</a></div></div><div class="two-language"><div><div class="reference">ENGLISH</div><p>${esc(s.storyEn)}</p></div><div dir="rtl"><div class="reference">العربية</div><p class="arabic">${esc(s.storyAr)}</p></div></div><p class="meaning">Sources and further reading: <a href="https://www.vatican.va/news_services/liturgy/saints/ns_lit_doc_20040516_al-hardini_en.html" target="_blank" rel="noopener">Vatican biography of Nimatullah</a> · <a href="https://press.vatican.va/news_services/liturgy/saints/ns_lit_doc_20010610_rafqa-choboq_en.html" target="_blank" rel="noopener">Vatican biography of Rafqa</a> · <a href="https://gcatholic.org/saints/data/country-LB" target="_blank" rel="noopener">Lebanese saints and blesseds reference list</a> · <a href="https://www.vatican.va/content/benedict-xvi/en/audiences/2010/documents/hf_ben-xvi_aud_20100210.html" target="_blank" rel="noopener">Vatican biography of Anthony of Padua</a> · <a href="https://www.vatican.va/news_services/liturgy/saints/ns_lit_doc_20020616_padre-pio_en.html" target="_blank" rel="noopener">Vatican biography of Padre Pio</a> · <a href="https://www.vatican.va/content/leo-xiv/en/events/event.dir.html/content/vaticanevents/en/2025/10/19/canonizzazioni.html" target="_blank" rel="noopener">Vatican canonisation of Ignatius Maloyan</a> · <a href="https://www.vaticannews.va/en/pope/news/2026-07/pope-leo-angelus-beatification-elias-hoayek-lebanon-prayers.html" target="_blank" rel="noopener">Vatican News on Blessed Elias Hoayek</a> · <a href="https://maronite.org.au/news-events/" target="_blank" rel="noopener">Maronite Eparchy biographies and news</a> · <a href="https://www.vaticanstate.va/en/component/content/article/july-24-saint-charbel-makhlouf.html?Itemid=216&catid=51" target="_blank" rel="noopener">Eastern and Maronite Lebanese saints</a>.</p><p class="meaning">Canonisation status is shown separately from traditional veneration. Biographies are concise summaries; dates and historical details are based on published Church biographies and reference lists.</p></div>`;
    output.querySelector("[data-saints-back]").addEventListener("click",renderSaints);
    loadSaintImages([s]);
  }
  function renderSaints(){
    panelTitle.textContent="Saints from Lebanon & around the world · قدّيسو لبنان والعالم";
    const letters=[..."ABCDEFGHIJKLMNOPQRSTUVWXYZ"];
    output.innerHTML=`<p class="meaning">A carefully curated guide to Lebanon’s best-known saints and blesseds, alongside beloved saints from the universal Church. / دليل منتقى لأشهر قدّيسي لبنان وطوباويّيه، إلى جانب قدّيسي الكنيسة الجامعة المعروفين.</p><div class="saints-toolbar"><input class="saints-search" id="saintsSearch" type="search" placeholder="Search a name, place or status… / ابحث عن اسم أو منطقة"><select id="saintsGroup" class="saints-search" aria-label="Filter saints"><option value="All">All ${entries.length} profiles</option><option value="Lebanese">Lebanese saints & blesseds</option><option value="Worldwide">Saints from around the world</option></select><div class="alphabet" id="saintsAlphabet"></div></div><div class="saints-grid" id="saintsGrid"></div><p class="meaning">A curated collection of ${entries.length} profiles. Lebanese saints and blesseds appear first, followed by widely loved saints from around the world. Each profile includes a fuller story in English and Arabic.</p>`;
    let letter="";
    const alphabet=$("#saintsAlphabet");
    letters.forEach(ch=>{const b=document.createElement("button");b.textContent=ch;b.addEventListener("click",()=>{letter=letter===ch?"":ch;draw()});alphabet.appendChild(b)});
    const draw=()=>{
      const q=$("#saintsSearch").value.toLowerCase().trim();
      alphabet.querySelectorAll("button").forEach(b=>b.classList.toggle("active",b.textContent===letter));
      const group=$("#saintsGroup").value;
      const found=entries.filter(s=>(group==="All"||s.group===group)&&(!letter||s.letter===letter)&&(s.en+" "+s.ar+" "+s.place+" "+s.status).toLowerCase().includes(q));
      $("#saintsGrid").innerHTML=found.length?found.map((s,i)=>`<button class="saint-card" data-saint-index="${entries.indexOf(s)}">${saintPortrait(s)}<div class="saint-card-copy"><span class="saint-letter">${esc(s.letter)}</span><span class="saint-status">${esc(s.status)}</span><h3>${esc(s.en)}</h3><p lang="ar" dir="rtl">${esc(s.ar)}</p><p>${esc(s.place)}</p></div></button>`).join(""):'<p class="meaning">No matching names. Try another spelling or letter.</p>';
      $("#saintsGrid").querySelectorAll("[data-saint-index]").forEach(b=>b.addEventListener("click",()=>openSaint(entries[Number(b.dataset.saintIndex)])));
      loadSaintImages(found);
    };
    $("#saintsSearch").addEventListener("input",draw);$("#saintsGroup").addEventListener("change",draw);draw();
  }
  function renderPriest(){
    panelTitle.textContent="Sunday worship · الحياة الكنسية";
    output.innerHTML=`<div class="saint-detail"><p class="section-kicker">THE SUNDAY LITURGY</p><h3>Gathered around the altar.</h3><p>In the Sunday Divine Liturgy, the community gathers to hear the Word, pray together and celebrate the Eucharist. The priest presides at the altar in service to the people and the Church.</p><p class="arabic" lang="ar" dir="rtl">في القداس الإلهي يوم الأحد، تجتمع الجماعة لسماع كلمة الله والصلاة معًا والاحتفال بالقربان المقدّس. ويترأس الكاهن الصلاة عند المذبح في خدمة المؤمنين والكنيسة.</p><p class="meaning">A simple guide to the parts of the Mass, the liturgical year and the people who serve in the Church will be added here.</p><button class="text-button" data-action="daily">Read today's liturgy ↗</button></div>`;
  }
  window.addEventListener("verbum:view",e=>{if(e.detail==="saints")renderSaints();if(e.detail==="priest")renderPriest()});
})();
